'use client'

import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { Badge } from '@/components/ui/badge'
import { Drama, AlertCircle } from 'lucide-react'
import { ResizablePanel, ResizablePanelGroup } from '@/components/ui/resizable'
import { useSSE } from '@/hooks/useSSE'
import { useLibrary } from '@/contexts/LibraryContext'

export default function TBSPersonasPage() {
  const navigate = useNavigate()
  const sseState = useSSE()
  const { getAuthHeaders } = useLibrary()
  const currentPersona = sseState.personaId || 'default'
  const [personas, setPersonas] = useState<any[]>([])
  const [systemPersonas, setSystemPersonas] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    fetchPersonas()
    fetchSystemPersonas()
  }, [])

  const fetchPersonas = async () => {
    console.log('Fetching local personas from API...')
    try {
      const response = await fetch('/api/personas')
      console.log('Local personas response status:', response.status)

      if (!response.ok) throw new Error('Failed to fetch personas')

      const data = await response.json()
      console.log('Local personas raw response:', data)

      // The API returns Persona objects - use them AS IS
      const personasArray = data.personas || []

      // Debug: Show what we got for each persona
      console.log('=== Loading Local Persona Details ===')
      personasArray.forEach((persona: any, index: number) => {
        console.log(`Persona ${index + 1}:`)
        console.log('  - Name:', persona.name)
        console.log('  - Profile:', persona.profile)
        console.log('  - Metadata:', persona.metadata)
        console.log('  - Files:', persona.files)
        console.log('  - Full object:', persona)
        console.log('---')
      })
      console.log('=== End Local Persona Details ===')

      // Just store the personas directly
      setPersonas(personasArray)
    } catch (err) {
      setError('Failed to load personas')
      console.error('Error fetching personas:', err)
    } finally {
      setLoading(false)
    }
  }

  const fetchSystemPersonas = async () => {
    try {
      const authHeaders = getAuthHeaders()
      console.log('Fetching library personas with headers:', authHeaders)

      const response = await fetch('/api/library/personas', {
        headers: authHeaders || {}
      })

      console.log('Library personas response status:', response.status)

      if (!response.ok) {
        const errorText = await response.text()
        console.error('Failed to fetch library personas:', response.status, errorText)
        return
      }

      const data = await response.json()
      console.log('Library personas raw response:', data)

      // Ensure we always have an array
      const personas = Array.isArray(data.personas) ? data.personas :
                      Array.isArray(data) ? data : []
      console.log('Processed library personas:', personas)
      setSystemPersonas(personas)
    } catch (err) {
      console.error('Error fetching system personas:', err)
      setSystemPersonas([]) // Ensure array on error
    }
  }

  // Removed unused function extractDescription

  const getPersonaIcon = (name: string | undefined) => {
    const colors = [
      'bg-orange-100 dark:bg-orange-900/20 text-orange-500',
      'bg-blue-100 dark:bg-blue-900/20 text-blue-500',
      'bg-purple-100 dark:bg-purple-900/20 text-purple-500',
      'bg-green-100 dark:bg-green-900/20 text-green-500',
      'bg-pink-100 dark:bg-pink-900/20 text-pink-500',
    ]
    if (!name || typeof name !== 'string' || name.length === 0) {
      return colors[0] // Default to first color if name is invalid
    }
    const colorIndex = name.charCodeAt(0) % colors.length
    return colors[colorIndex]
  }

  return (
    <div className="h-full">
      <ResizablePanelGroup direction="horizontal">
        <ResizablePanel defaultSize={100} minSize={30}>
          <div className="overflow-auto h-full">
            <div className="p-4 md:p-6 lg:p-8 mx-auto max-w-7xl space-y-6">
              {/* Error State */}
              {error && (
                <Card className="border-destructive">
                  <CardContent className="flex items-center gap-2 pt-6">
                    <AlertCircle className="h-5 w-5 text-destructive" />
                    <p className="text-sm text-destructive">{error}</p>
                  </CardContent>
                </Card>
              )}

              {/* Local Personas Section */}
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle className="text-xl">Local Personas</CardTitle>
                      <CardDescription>
                        Your local personas and customizations
                      </CardDescription>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  {/* Loading State */}
                  {loading && (
                    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                      {[1, 2, 3].map((i) => (
                        <Card key={i}>
                          <CardHeader>
                            <Skeleton className="h-12 w-12 rounded-lg mb-3" />
                            <Skeleton className="h-4 w-3/4" />
                            <Skeleton className="h-3 w-1/2 mt-2" />
                          </CardHeader>
                          <CardContent>
                            <Skeleton className="h-16 w-full" />
                          </CardContent>
                        </Card>
                      ))}
                    </div>
                  )}

                  {/* Personas Grid */}
                  {!loading && (
                    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                      {personas.length === 0 && !error && (
                        <Card className="col-span-full">
                          <CardContent className="text-center py-12">
                            <Drama className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
                            <p className="text-lg font-medium mb-2">No personas found</p>
                            <p className="text-sm text-muted-foreground">
                              Create your first persona or sync from the library
                            </p>
                          </CardContent>
                        </Card>
                      )}

                      {personas.map((persona) => {
                        // Now the persona has a name property added by the route
                        const personaName = persona.name
                        return (
                          <Card
                            key={personaName}
                            className={`hover:shadow-lg transition-shadow cursor-pointer relative
                              ${personaName === currentPersona
                                ? 'ring-2 ring-primary border-primary/50 bg-primary/5'
                                : ''}`}
                            onClick={() => navigate(`/personas/${personaName}`)}
                          >
                            {personaName === currentPersona && (
                              <Badge className="absolute top-2 right-2 bg-primary" variant="default">
                                Active
                              </Badge>
                            )}
                            <CardHeader>
                              <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3 flex-1">
                                  <div className={`p-2 rounded-lg ${getPersonaIcon(personaName)}`}>
                                    <Drama className="h-6 w-6" />
                                  </div>
                                  <div className="flex-1 min-w-0">
                                    <CardTitle className="text-lg truncate">{personaName}</CardTitle>
                                    <CardDescription className="line-clamp-2">
                                      {persona.persona?.system?.metadata?.description || persona.metadata?.description || 'Local persona configuration'}
                                    </CardDescription>
                                  </div>
                                </div>
                              </div>
                            </CardHeader>
                            <CardContent>
                              <div className="space-y-2">
                                <div className="flex flex-wrap gap-1.5">
                                  {persona.metadata?.tags?.[0] && (
                                    <Badge variant="outline" className="text-xs">
                                      {persona.metadata.tags[0]}
                                    </Badge>
                                  )}
                                  {persona.metadata?.version && (
                                    <Badge variant="outline" className="text-xs">
                                      v{persona.metadata.version}
                                    </Badge>
                                  )}
                                </div>
                                {persona.metadata?.tags && persona.metadata.tags.length > 0 && (
                                  <div className="flex flex-wrap gap-1">
                                    {persona.metadata.tags.slice(0, 3).map((tag: string, idx: number) => (
                                      <span key={idx} className="text-xs text-muted-foreground">
                                        #{tag}
                                      </span>
                                    ))}
                                  </div>
                                )}
                                {persona.metadata?.sourceLibrary && (
                                  <div className="mt-3 p-2 rounded-md border border-purple-200/50 dark:border-purple-800/30 bg-gradient-to-br from-blue-100/30 via-purple-100/20 to-pink-100/30 dark:from-blue-950/20 dark:via-purple-950/15 dark:to-pink-950/20">
                                    <div className="flex items-center gap-2">
                                      <div className={`p-1 rounded ${getPersonaIcon(persona.metadata.sourceLibrary.name)}`}>
                                        <Drama className="h-3 w-3" />
                                      </div>
                                      <div className="flex-1 min-w-0">
                                        <p className="text-xs font-medium truncate">
                                          {persona.metadata.sourceLibrary.name}
                                        </p>
                                        <p className="text-[10px] text-muted-foreground">
                                          Library v{persona.metadata.sourceLibrary.version}
                                        </p>
                                      </div>
                                    </div>
                                  </div>
                                )}
                              </div>
                            </CardContent>
                          </Card>
                        )
                      })}
                    </div>
                  )}
                </CardContent>
              </Card>

              {/* Library Personas Section */}
              <Card>
                <CardHeader>
                  <div>
                    <CardTitle>Persona Library</CardTitle>
                    <CardDescription>
                      Available personas from the Tiny Brain library
                    </CardDescription>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">
                    {!Array.isArray(systemPersonas) || systemPersonas.length === 0 ? (
                      <div className="col-span-full text-center py-8">
                        <Drama className="h-8 w-8 text-muted-foreground mx-auto mb-3" />
                        <p className="text-sm font-medium mb-1">No Library Personas</p>
                        <p className="text-xs text-muted-foreground">
                          Library personas will appear here once available
                        </p>
                      </div>
                    ) : (
                      systemPersonas.map((persona, index) => (
                        <div
                          key={persona.path || `persona-${index}`}
                          className="p-4 rounded-lg border border-purple-200/50 dark:border-purple-800/30 hover:border-purple-300/70 dark:hover:border-purple-700/50 hover:shadow-md transition-all relative overflow-hidden bg-gradient-to-br from-blue-100/30 via-purple-100/20 to-pink-100/30 dark:from-blue-950/20 dark:via-purple-950/15 dark:to-pink-950/20 cursor-pointer select-none"
                        >
                          <div className="flex items-start gap-3 relative">
                            <div className={`p-2 rounded-lg shrink-0 ${getPersonaIcon(persona.metadata?.name)}`}>
                              <Drama className="h-5 w-5" />
                            </div>
                            <div className="flex-1 min-w-0 pr-12">
                              <div className="flex items-center gap-2">
                                <p className="font-medium">{persona.metadata?.name || 'Unnamed'}</p>
                              </div>
                              <p className="text-xs text-muted-foreground mt-1 line-clamp-2">
                                {persona.metadata?.description || 'No description available'}
                              </p>
                              <div className="flex flex-wrap gap-1.5 mt-2">
                                {persona.metadata?.category && (
                                  <Badge variant="outline" className="text-xs">
                                    {persona.metadata.category}
                                  </Badge>
                                )}
                                {persona.metadata?.version && (
                                  <Badge variant="outline" className="text-xs">
                                    v{persona.metadata.version}
                                  </Badge>
                                )}
                              </div>
                            </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
        </ResizablePanel>
      </ResizablePanelGroup>
    </div>
  )
}