import React from 'react';
import { Clock, DollarSign } from 'lucide-react';
import type { TechnicalDebtSummary, QualityIssue } from '../types';

interface QualityTechnicalDebtProps {
  technicalDebt?: TechnicalDebtSummary;
  issues?: QualityIssue[];
}

export const QualityTechnicalDebt: React.FC<QualityTechnicalDebtProps> = ({
  technicalDebt,
}) => {
  if (!technicalDebt) {
    return null;
  }

  const { totalHours: rawHours, estimatedCost, currency } = technicalDebt;
  const totalHours = rawHours ?? 0;

  const formattedCost = estimatedCost
    ? new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: currency || 'USD',
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
      }).format(estimatedCost)
    : null;

  return (
    <div className="border border-gray-200 dark:border-gray-700 rounded-lg p-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Clock className="h-4 w-4 text-gray-500" />
          <span className="text-sm text-gray-700 dark:text-gray-300">
            Technical Debt
          </span>
          <span className="text-sm text-gray-900 dark:text-gray-100">
            <span className="font-bold">{totalHours.toFixed(1)}</span> agentic hours
          </span>
          {formattedCost && (
            <span className="flex items-center gap-1 text-sm text-gray-600 dark:text-gray-400">
              <DollarSign className="h-3 w-3" />
              {formattedCost}
            </span>
          )}
        </div>
        {/* intentionally empty — plan tab available above */}
      </div>
    </div>
  );
};

export default QualityTechnicalDebt;
