import React, { useMemo } from 'react';
import { cn } from '@/lib/utils';
import { Archive, GitBranch } from 'lucide-react';
import ProgressBar from './ProgressBar';
import { SelectableCard } from './ui/selectable-card';
import type { Fix } from '../types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { taskPhaseProgress } from '../utils/task-progress';

interface FixCardProps {
  fix: Fix;
  isSelected: boolean;
  onClick: () => void;
  reviewPipeline?: PipelineStep[];
}

const severityColors = {
  low: 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300',
  medium: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300',
  high: 'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-300',
  critical: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300',
};

const displayStatus: Record<Fix['status'], string> = {
  not_started: 'Not Started',
  in_progress: 'In Progress',
  completed: 'Complete',
  superseded: 'Superseded',
};

const FixCard: React.FC<FixCardProps> = ({ fix, isSelected, onClick, reviewPipeline }) => {
  const taskWorktrees = useMemo(() => {
    const seen = new Set<string>();
    const result: Array<{ name: string; branch: string }> = [];
    for (const task of fix.tasks) {
      if (task.worktree && !seen.has(task.worktree.name)) {
        seen.add(task.worktree.name);
        result.push(task.worktree);
      }
    }
    return result;
  }, [fix.tasks]);

  const { progress, completedPercent, supersededPercent } = useMemo(() => {
    if (fix.status === 'completed' || fix.status === 'superseded') {
      const pct = fix.status === 'superseded' ? 'supersededPercent' : 'completedPercent';
      return { progress: 100, completedPercent: pct === 'completedPercent' ? 100 : 0, supersededPercent: pct === 'supersededPercent' ? 100 : 0 };
    }
    const total = fix.tasks.length;
    if (total === 0) return { progress: 0, completedPercent: 0, supersededPercent: 0 };

    // Sum fractional progress per task (pipeline-phase-aware)
    let completedWeight = 0;
    let supersededWeight = 0;
    for (const task of fix.tasks) {
      const fraction = taskPhaseProgress(task, reviewPipeline);
      if (task.status === 'superseded') {
        supersededWeight += fraction;
      } else {
        completedWeight += fraction;
      }
    }

    return {
      progress: Math.round(((completedWeight + supersededWeight) / total) * 100),
      completedPercent: Math.round((completedWeight / total) * 100),
      supersededPercent: Math.round((supersededWeight / total) * 100),
    };
  }, [fix.status, fix.tasks, reviewPipeline]);

  const isResolved = fix.status === 'completed' || fix.status === 'superseded';
  const isInProgress = fix.status === 'in_progress';
  const isArchived = fix.archived === true;

  return (
      <SelectableCard
        isSelected={isSelected}
        isCompleted={isResolved}
        onClick={onClick}
        className={cn(
          isArchived && "opacity-60",
          isInProgress && "bg-blue-100/60 dark:bg-blue-900/30"
        )}
        data-testid={isArchived ? 'archived-card' : undefined}
      >
        <div className="flex items-start justify-between gap-2">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-1">
              {isArchived && <Archive data-testid="archive-icon" className="h-3.5 w-3.5 text-muted-foreground flex-shrink-0" />}
              <h3 className="font-medium text-sm line-clamp-2">{fix.title}</h3>
            </div>
          </div>
          <span className={cn(
            'text-xs px-2 py-0.5 rounded-full font-medium whitespace-nowrap',
            severityColors[fix.severity]
          )}>
            {fix.severity}
          </span>
        </div>

        {/* Progress */}
        <div className="space-y-2 mt-2">
          <div className="flex justify-between text-xs">
            <span className={cn(
              isResolved ? "text-green-600 dark:text-green-400 font-medium" :
              isInProgress ? "text-blue-600 dark:text-blue-400 font-medium"
                : "text-gray-500 dark:text-gray-400"
            )}>{isResolved ? '✅ Complete!' : displayStatus[fix.status]}</span>
            <span className={cn("text-muted-foreground", isResolved && "font-bold text-green-600 dark:text-green-400")}>{progress}%</span>
          </div>
          <ProgressBar
            progress={progress}
            isSelected={isSelected}
            isInProgress={isInProgress}
            completedPercent={completedPercent}
            supersededPercent={supersededPercent}
          />
        </div>

        {/* Worktree source badge */}
        {fix.sourceWorktree && (
          <div className="mt-2">
            <span
              data-testid="source-worktree-badge"
              title={fix.sourceWorktree.branch}
              className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-xs bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-300"
            >
              <GitBranch className="h-3 w-3" />
              {fix.sourceWorktree.name}
            </span>
          </div>
        )}

        {/* Task-derived worktree badges */}
        {taskWorktrees.length > 0 && (
          <div className="mt-2 flex flex-wrap gap-1">
            {taskWorktrees.map(wt => (
              <span
                key={wt.name}
                data-testid="task-worktree-badge"
                title={wt.branch}
                className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-xs bg-indigo-100 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-300"
              >
                <GitBranch className="h-3 w-3" />
                {wt.name}
              </span>
            ))}
          </div>
        )}

        {/* Date info */}
        {fix.reported && (
          <div className="mt-2 text-xs text-muted-foreground">
            Reported: {new Date(fix.reported).toLocaleDateString()}
            {fix.resolved && (
              <span className="ml-2">
                Resolved: {new Date(fix.resolved).toLocaleDateString()}
              </span>
            )}
          </div>
        )}
      </SelectableCard>
  );
};

export default FixCard;
