const hasScripts = (scripts?: RepoAnalysisFile['scripts']): boolean => {
  if (!scripts) return false;
  return !!(scripts.test?.command || scripts.build?.command || scripts.dev?.command || scripts.lint?.command || scripts.e2e?.command);
};

