// --- Wizard Step Indicator ---

interface WizardStep {
  label: string;
  complete: boolean;
  ready?: boolean;
}

const StepIndicator: React.FC<{
  steps: WizardStep[];
  currentStep: number;
  onStepClick: (index: number) => void;
}> = ({ steps, currentStep, onStepClick }) => (
  <div className="flex items-center justify-center gap-0 pt-1 pb-5 border-b border-border mb-4">
    {steps.map((step, index) => (
      <React.Fragment key={step.label}>
        {index > 0 && (
          <div
            className={`h-0.5 w-8 self-center ${
              index <= currentStep ? 'bg-blue-500' : 'bg-gray-300 dark:bg-gray-600'
            }`}
          />
        )}
        <button
          onClick={() => onStepClick(index)}
          className={`flex items-center gap-2 px-3 py-2 rounded-lg border transition-colors cursor-pointer bg-white dark:bg-gray-900 ${
            step.ready
              ? index === currentStep
                ? 'border-purple-400 dark:border-purple-600'
                : 'border-purple-200 dark:border-purple-800 hover:border-purple-400 dark:hover:border-purple-600'
            : index === currentStep
              ? 'border-blue-500'
              : step.complete
              ? 'border-green-200 dark:border-green-800 hover:border-green-400 dark:hover:border-green-600'
              : 'border-gray-200 dark:border-gray-700 hover:border-gray-400 dark:hover:border-gray-500'
          }`}
        >
          <div
            className={`flex items-center justify-center w-6 h-6 rounded-full text-xs font-semibold border-2 transition-colors shrink-0 ${
              step.complete
                ? 'bg-green-600 border-green-600 text-white'
                : step.ready
                ? 'bg-gradient-to-br from-pink-500 to-purple-600 border-purple-500 text-white'
                : index === currentStep
                ? 'bg-blue-600 border-blue-600 text-white'
                : 'bg-gray-200 dark:bg-gray-700 border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-300'
            }`}
          >
            {step.complete ? <Check className="h-3.5 w-3.5" style={{ color: 'white', strokeWidth: 3 }} /> : index + 1}
          </div>
          <span
            className={`text-xs font-medium ${
              step.ready
                ? 'text-purple-600 dark:text-purple-400'
                : index === currentStep
                ? 'text-blue-700 dark:text-blue-300'
                : step.complete
                ? 'text-green-600 dark:text-green-400'
                : 'text-gray-400 dark:text-gray-500'
            }`}
          >
            {step.label}
          </span>
        </button>
      </React.Fragment>
    ))}
  </div>
);

// --- Validation helpers (shared with SkillList pattern) ---

type RecommendationValidationState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; result: SkillValidationResult }
  | { status: 'error'; message: string };

function getCheckStatus(check: SkillValidationCheck): 'pass' | 'warn' | 'fail' | 'info' {
  if (check.passed) {
    return 'pass';
  }
  if (check.severity === 'error') {
    return 'fail';
  }
  if (check.severity === 'warning') {
    return 'warn';
  }
  return 'info';
}

function ValidationCheckIcon({ status }: { status: 'pass' | 'warn' | 'fail' | 'info' }) {
  switch (status) {
    case 'pass':
      return <CheckCircle2 className="h-4 w-4 text-green-500 shrink-0" />;
    case 'fail':
      return <XCircle className="h-4 w-4 text-red-500 shrink-0" />;
    case 'warn':
      return <AlertTriangle className="h-4 w-4 text-yellow-500 shrink-0" />;
    case 'info':
      return <Info className="h-4 w-4 text-blue-500 shrink-0" />;
  }
}

// --- Recommendation Card ---

interface AcceptResult {
  success: boolean;
  installedPath?: string;
  error?: string;
}

interface RecommendationCardProps {
  recommendation: DashboardRecommendation;
  onAccept: () => void;
  onDismiss: () => void;
  isAccepting?: boolean;
  acceptResult?: AcceptResult;
  validationState?: RecommendationValidationState;
  onAnalyse?: () => void;
}

const RecommendationCard: React.FC<RecommendationCardProps> = ({ recommendation, onAccept, onDismiss, isAccepting, acceptResult, validationState, onAnalyse }) => {
  const colors = typeBadgeColors[recommendation.type] ?? { bg: 'bg-gray-100', text: 'text-gray-700' };
  const isSkill = recommendation.type === 'skill';
  const vState = validationState ?? { status: 'idle' as const };

  const renderButtons = () => {
    if (acceptResult?.success) {
      return (
        <div className="flex items-center gap-2 flex-shrink-0">
          <span className="flex items-center gap-1 text-xs font-medium text-green-700 dark:text-green-300">
            <CheckCircle2 className="h-4 w-4" />
            Installed
          </span>
        </div>
      );
    }

    return (
      <div className="flex items-center gap-2 flex-shrink-0">
        {isSkill && (
          vState.status === 'loading' ? (
            <span className="flex items-center gap-1 text-xs text-muted-foreground">
              <Loader2 className="h-3 w-3 animate-spin" />
              Analysing...
            </span>
          ) : (
            <button
              onClick={onAnalyse}
              className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium rounded-md text-muted-foreground hover:bg-muted border border-border transition-colors"
              aria-label={`Analyse ${recommendation.name}`}
            >
              <Search className="h-3 w-3" />
              Analyse
            </button>
          )
        )}
        <button
          onClick={onAccept}
          disabled={isAccepting}
          className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium rounded-md bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-300 hover:bg-green-100 dark:hover:bg-green-900/30 border border-green-200 dark:border-green-800 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          aria-label={`Accept ${recommendation.name}`}
        >
          {isAccepting ? (
            <>
              <Loader2 className="h-3 w-3 animate-spin" />
              Installing...
            </>
          ) : (
            <>
              <Check className="h-3 w-3" />
              Accept
            </>
          )}
        </button>
        <button
          onClick={onDismiss}
          disabled={isAccepting}
          className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium rounded-md text-muted-foreground hover:bg-muted border border-border transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          aria-label={`Dismiss ${recommendation.name}`}
        >
          <X className="h-3 w-3" />
          Dismiss
        </button>
      </div>
    );
  };

  return (
    <div className="border border-border rounded-lg p-4 bg-card">
      <div className="flex items-start justify-between gap-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <h4 className="font-medium text-sm">{recommendation.name}</h4>
            <span className={`text-xs px-2 py-0.5 rounded ${colors.bg} ${colors.text}`}>
              {recommendation.type}
            </span>
            <span className="text-xs px-2 py-0.5 rounded bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400">
              {recommendation.category}
            </span>
            {recommendation.validation && vState.status === 'idle' && (
              <GradePill grade={recommendation.validation.grade} />
            )}
          </div>
          <p className="text-sm text-muted-foreground">{recommendation.description}</p>
          <p className="text-xs text-muted-foreground mt-1 italic">{recommendation.reason}</p>
          {recommendation.tags.length > 0 && (
            <div className="flex flex-wrap gap-1 mt-2">
              {recommendation.tags.map(tag => (
                <span key={tag} className="px-1.5 py-0.5 text-xs rounded bg-muted text-muted-foreground">
                  {tag}
                </span>
              ))}
            </div>
          )}
          {acceptResult?.success && acceptResult.installedPath && (
            <p className="text-xs text-muted-foreground mt-2 font-mono">{acceptResult.installedPath}</p>
          )}
          {acceptResult && !acceptResult.success && (
            <p className="text-xs text-red-600 dark:text-red-400 mt-2">{acceptResult.error}</p>
          )}
        </div>
        {renderButtons()}
      </div>

      {vState.status === 'success' && (
        <div className="mt-3 p-3 rounded-lg border border-border bg-card/50 space-y-2">
          <div className="flex items-center gap-2">
            <GradePill grade={vState.result.grade} score={vState.result.score} />
          </div>
          {vState.result.checks.length > 0 && (
            <div className="space-y-1">
              {vState.result.checks.map((check) => {
                const status = getCheckStatus(check);
                return (
                  <div
                    key={check.id}
                    data-check-status={status}
                    className="flex items-start gap-2 text-xs"
                  >
                    <ValidationCheckIcon status={status} />
                    <span className="text-muted-foreground">{check.message}</span>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {vState.status === 'error' && (
        <div className="mt-3 p-3 rounded-lg border border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-950/30">
          <p className="text-xs text-red-600 dark:text-red-400">{vState.message}</p>
        </div>
      )}
    </div>
  );
};

// --- Main Component ---

const SetupTab: React.FC<SetupTabProps> = ({ repoId, repoPath, onNavigateToPlans, onSetupComplete }) => {
  // Data state
  const [health, setHealth] = useState<ConfigHealth | null>(null);
  const [flags, setFlags] = useState<ConfigFlags | null>(null);
  const [analysisData, setAnalysisData] = useState<{ exists: boolean; analysis: RepoAnalysisFile | null; agentsMdStatus?: { exists: boolean; lastModified?: string; content?: string }; agentsMdFiles?: Array<{ path: string; exists: boolean; lastModified?: string; content?: string }>; packageScripts?: Array<{ package: string; name?: string; scripts: Record<string, string> }> }>({ exists: false, analysis: null });
  const [recommendations, setRecommendations] = useState<DashboardRecommendation[]>([]);
  const [dismissed, setDismissed] = useState<DismissedRecommendation[]>([]);
  const [installedData, setInstalledData] = useState<InstalledData>({ agents: [], skills: [], plugins: [], pluginHooks: [] });
  const [loading, setLoading] = useState(true);

  // Wizard state
  const [currentStep, setCurrentStep] = useState(0);

  // Accept status state
  const [acceptingIds, setAcceptingIds] = useState<Set<string>>(new Set());
  const [acceptResults, setAcceptResults] = useState<Map<string, AcceptResult>>(new Map());
  const [installedCapTypes, setInstalledCapTypes] = useState<string[]>([]);

  // UI state
  const [dismissedExpanded, setDismissedExpanded] = useState(false);
  const [activeGuardrailItem, setActiveGuardrailItem] = useState('overview');
  const [activeAnalysisItem, setActiveAnalysisItem] = useState('overview');

  // Analysis state
  const [analyzing, setAnalyzing] = useState(false);
  const [progressSteps, setProgressSteps] = useState<ProgressStep[]>([]);
  const [analysisError, setAnalysisError] = useState<string | null>(null);

  const { hasClaudeCli } = useApiKeyStatus();

  // --- Step completion logic ---
  const isGuardrailsComplete = health?.status === 'healthy';
  const isAnalysisComplete = analysisData.exists;
  const isRecommendationsComplete = recommendations.length === 0;
  const isSetupComplete = !!isGuardrailsComplete && isAnalysisComplete && isRecommendationsComplete;

  useEffect(() => {
    if (!loading) onSetupComplete?.(isSetupComplete);
  }, [loading, isSetupComplete, onSetupComplete]);

  const steps: WizardStep[] = [
    { label: 'Guardrails', complete: !!isGuardrailsComplete },
    { label: 'Analysis', complete: isAnalysisComplete },
    { label: 'Pipelines', complete: isRecommendationsComplete },
    { label: 'Ready', complete: false, ready: !!isGuardrailsComplete && isAnalysisComplete && isRecommendationsComplete },
  ];

  // --- Installed data fetching (agents, skills, plugins, hooks) ---
  const refreshInstalledData = useCallback(async () => {
    try {
      const fetches: Promise<Response>[] = [
        fetch(`/api/repos/${repoId}/agents`),
        fetch(`/api/repos/${repoId}/skills`),
      ];

      if (repoPath) {
        fetches.push(
          fetch(`/api/plugins/repo/${encodeURIComponent(repoPath)}`),
          fetch(`/api/hooks?repoPath=${encodeURIComponent(repoPath)}`),
        );
      }

      const [agentsRes, skillsRes, pluginsRes, hooksRes] = await Promise.all(fetches);

      const data: InstalledData = { agents: [], skills: [], plugins: [], pluginHooks: [] };
      if (agentsRes?.ok) {
        const agentsData = await agentsRes.json();
        data.agents = agentsData.agents ?? [];
      }
      if (skillsRes?.ok) {
        const skillsData = await skillsRes.json();
        data.skills = skillsData.skills ?? [];
      }
      if (pluginsRes?.ok) {
        const pluginsData = await pluginsRes.json();
        data.plugins = pluginsData.plugins ?? [];
      }
      if (hooksRes?.ok) {
        const hooksData = await hooksRes.json();
        data.pluginHooks = hooksData.pluginHooks ?? [];
      }
      setInstalledData(data);
    } catch {
      // Silently handle fetch errors
    }
  }, [repoId, repoPath]);

  // --- Data fetching ---
  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const fetches: Promise<Response>[] = [
        fetch(`/api/repos/${repoId}/config-health`),
        fetch(`/api/repos/${repoId}/feature-flags`),
        fetch(`/api/repos/${repoId}/analysis`),
        fetch(`/api/repos/${repoId}/recommendations`),
        fetch(`/api/repos/${repoId}/recommendations/dismissed`),
      ];

      const results = await Promise.all(fetches);
      const [healthRes, flagsRes, analysisRes, recsRes, dismissedRes] = results;

      if (healthRes.ok) {
        const healthData = await healthRes.json();
        setHealth(healthData.health);
      }
      if (flagsRes.ok) {
        const flagsData = await flagsRes.json();
        setFlags(flagsData.flags);
      }
      if (analysisRes.ok) {
        const analysisJson = await analysisRes.json();
        setAnalysisData({ exists: analysisJson.exists, analysis: analysisJson.analysis, agentsMdStatus: analysisJson.agentsMdStatus, agentsMdFiles: analysisJson.agentsMdFiles, packageScripts: analysisJson.packageScripts });
      }
      if (recsRes.ok) {
        const recsData = await recsRes.json();
        setRecommendations(recsData.recommendations ?? []);
      }
      if (dismissedRes.ok) {
        const dismissedData = await dismissedRes.json();
        setDismissed(dismissedData.dismissed ?? []);
      }

      await refreshInstalledData();
    } catch {
      // Silently handle fetch errors
    } finally {
      setLoading(false);
    }
  }, [repoId, repoPath, refreshInstalledData]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Refresh recommendations when background scheduler finds new ones
  useEffect(() => {
    const unsubscribe = sseManager.on('recommendationsUpdated', (event) => {
      if ('repoId' in event && event.repoId === repoId) {
        // Refetch just the recommendations
        Promise.all([
          fetch(`/api/repos/${repoId}/recommendations`),
          fetch(`/api/repos/${repoId}/recommendations/dismissed`),
        ]).then(async ([recsRes, dismissedRes]) => {
          if (recsRes.ok) {
            const recsData = await recsRes.json();
            setRecommendations(recsData.recommendations ?? []);
          }
          if (dismissedRes.ok) {
            const dismissedData = await dismissedRes.json();
            setDismissed(dismissedData.dismissed ?? []);
          }
        });
      }
    });
    return unsubscribe;
  }, [repoId]);

  // Auto-advance to first incomplete step after data loads
  useEffect(() => {
    if (loading) return;

    const healthComplete = health?.status === 'healthy';
    const analysisComplete = analysisData.exists;
    const recsComplete = recommendations.length === 0;

    if (!healthComplete) {
      setCurrentStep(0);
    } else if (!analysisComplete) {
      setCurrentStep(1);
    } else if (!recsComplete) {
      setCurrentStep(2);
    } else {
      setCurrentStep(3);
    }
  }, [loading, health, analysisData.exists, recommendations.length]);

  // --- SSE handlers for analysis ---
  const handleAnalysisEvent = useCallback((event: AnalysisChangeEvent) => {
    if (event.repoId !== repoId) return;

    if (event.eventType === 'analysis:complete') {
      setAnalysisData({ exists: true, analysis: event.analysis ?? null });
      setAnalyzing(false);
      setProgressSteps([]);
      setAnalysisError(null);

      // Re-fetch config health after analysis (which now includes config setup)
      Promise.all([
        fetch(`/api/repos/${repoId}/config-health`),
        fetch(`/api/repos/${repoId}/feature-flags`),
      ]).then(async ([healthRes, flagsRes]) => {
        if (healthRes.ok) {
          const data = await healthRes.json();
          setHealth(data.health);
        }
        if (flagsRes.ok) {
          const data = await flagsRes.json();
          setFlags(data.flags);
        }
      });
    } else if (event.eventType === 'analysis:failed') {
      setAnalysisError(event.error || 'Analysis failed');
      setAnalyzing(false);
      setProgressSteps([]);
    }
  }, [repoId]);

  const handleProgressEvent = useCallback((event: AnalysisProgressSSEEvent) => {
    if (event.repoId !== repoId) return;
    setProgressSteps(prev => [...prev, {
      type: event.eventType,
      message: event.message,
      timestamp: event.timestamp,
    }]);
  }, [repoId]);

  useEffect(() => {
    const unsubscribeAnalysis = sseManager.on('analysisChange', (event) => {
      handleAnalysisEvent(event as AnalysisChangeEvent);
    });
    const unsubscribeProgress = sseManager.on('analysisProgress', (event) => {
      handleProgressEvent(event as AnalysisProgressSSEEvent);
    });
    return () => {
      unsubscribeAnalysis();
      unsubscribeProgress();
    };
  }, [handleAnalysisEvent, handleProgressEvent]);

  // --- Analysis action ---
  const runAnalysis = async () => {
    setAnalyzing(true);
    setAnalysisError(null);
    setProgressSteps([]);
    try {
      const response = await fetch(`/api/repos/${repoId}/analysis`, { method: 'POST' });
      if (response.status === 202) return; // SSE will handle completion
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Analysis failed (${response.status})`);
      }
      const data = await response.json();
      if (data.analysis) {
        setAnalysisData({ exists: true, analysis: data.analysis });
        setAnalyzing(false);
        setProgressSteps([]);
      }
    } catch (err) {
      setAnalysisError(err instanceof Error ? err.message : 'Unknown error');
      setAnalyzing(false);
      setProgressSteps([]);
    }
  };

  // --- Recommendation actions ---
  const handleAccept = async (rec: DashboardRecommendation) => {
    setAcceptingIds(prev => { const next = new Set(prev); next.add(rec.id); return next; });
    setAcceptResults(prev => { const next = new Map(prev); next.delete(rec.id); return next; });

    try {
      const response = await fetch(`/api/repos/${repoId}/recommendations/accept`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: [rec.name] }),
      });

      setAcceptingIds(prev => { const next = new Set(prev); next.delete(rec.id); return next; });

      if (response.ok) {
        const data = await response.json() as { results?: Array<{ success: boolean; installedPath?: string; error?: string }> };
        const result = data.results?.[0];
        if (result?.success) {
          setAcceptResults(prev => new Map(prev).set(rec.id, { success: true, installedPath: result.installedPath }));
          await refreshInstalledData();

          // Add installed capability type to available list (appears hollow in both pipelines)
          const capType = ('installerId' in rec && rec.installerId) ? rec.installerId as string : rec.name;
          setInstalledCapTypes(prev => prev.includes(capType) ? prev : [...prev, capType]);

          setTimeout(() => {
            setRecommendations(prev => prev.filter(r => r.id !== rec.id));
            setAcceptResults(prev => { const next = new Map(prev); next.delete(rec.id); return next; });
          }, 1500);
        } else {
          setAcceptResults(prev => new Map(prev).set(rec.id, { success: false, error: result?.error ?? 'Installation failed' }));
        }
      } else {
        setAcceptResults(prev => new Map(prev).set(rec.id, { success: false, error: 'Request failed' }));
      }
    } catch {
      setAcceptingIds(prev => { const next = new Set(prev); next.delete(rec.id); return next; });
      setAcceptResults(prev => new Map(prev).set(rec.id, { success: false, error: 'Network error' }));
    }
  };

  const handleDismiss = async (rec: DashboardRecommendation) => {
    setRecommendations(prev => prev.filter(r => r.id !== rec.id));
    setDismissed(prev => [...prev, { recommendation: rec, dismissedAt: new Date().toISOString() }]);
    await fetch(`/api/repos/${repoId}/recommendations/dismiss`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: [rec.name] }),
    });
  };

  const handleRestore = async (item: DismissedRecommendation) => {
    setDismissed(prev => prev.filter(d => d.recommendation.id !== item.recommendation.id));
    setRecommendations(prev => [...prev, item.recommendation]);
    await fetch(`/api/repos/${repoId}/recommendations/restore`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: [item.recommendation.name] }),
    });
  };

  // --- Loading ---
  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        <span className="ml-2 text-muted-foreground">Loading...</span>
      </div>
    );
  }

  // --- Render ---
  return (
    <div className="h-full flex flex-col overflow-hidden bg-gradient-to-br from-pink-50/40 via-purple-50/30 to-blue-50/40 dark:from-pink-900/30 dark:via-purple-900/20 dark:to-blue-900/30 rounded-lg">
      {/* Step Indicator - centered */}
      <div className="flex-shrink-0 px-6 pt-4">
        <StepIndicator
          steps={steps}
          currentStep={currentStep}
          onStepClick={setCurrentStep}
        />
      </div>

      {/* Step Content - full width, scrollable */}
      <div className="flex-1 overflow-y-auto px-6 pb-6">
        {currentStep === 0 && (
          <GuardrailsStep
            health={health}
            flags={flags}
            repoId={repoId}
            installedData={installedData}
            activeItem={activeGuardrailItem}
            onItemSelect={setActiveGuardrailItem}
            onRunAnalysis={runAnalysis}
            onFlagsChange={setFlags}
            analyzing={analyzing}
            hasClaudeCli={hasClaudeCli}
          />
        )}

        {currentStep === 1 && (
          <AnalysisStep
            analysisData={analysisData}
            analyzing={analyzing}
            progressSteps={progressSteps}
            analysisError={analysisError}
            hasClaudeCli={hasClaudeCli}
            onRunAnalysis={runAnalysis}
            activeItem={activeAnalysisItem}
            onItemSelect={setActiveAnalysisItem}
          />
        )}

        {currentStep === 2 && (
          <RecommendationsStep
            repoId={repoId}
            recommendations={recommendations}
            dismissed={dismissed}
            dismissedExpanded={dismissedExpanded}
            setDismissedExpanded={setDismissedExpanded}
            onAccept={handleAccept}
            onDismiss={handleDismiss}
            onRestore={handleRestore}
            acceptingIds={acceptingIds}
            acceptResults={acceptResults}
            installedCapTypes={installedCapTypes}
            tddEnabled={flagBool(flags, 'enableTDD', true)}
            analysis={analysisData.analysis}
          />
        )}

        {currentStep === 3 && (
          <ReadyStep
            isGuardrailsComplete={!!isGuardrailsComplete}
            isAnalysisComplete={isAnalysisComplete}
            isRecommendationsComplete={isRecommendationsComplete}
            onNavigateToPlans={onNavigateToPlans}
          />
        )}
      </div>
    </div>
  );
};

