// --- Step 1: Guardrails ---

const GuardrailsStep: React.FC<{
  health: ConfigHealth | null;
  flags: ConfigFlags | null;
  repoId: string;
  installedData: InstalledData;
  activeItem: string;
  onItemSelect: (id: string) => void;
  onRunAnalysis: () => void;
  onFlagsChange: (flags: ConfigFlags) => void;
  analyzing: boolean;
  hasClaudeCli: boolean;
}> = ({ health, flags, repoId, installedData, activeItem, onItemSelect, onRunAnalysis, onFlagsChange, analyzing, hasClaudeCli }) => {
  const gitHooks = health ? [health.hooks.preCommit, health.hooks.commitMsg, health.hooks.postCommit] : [];
  const gitHooksInstalled = gitHooks.filter(h => h.installed);
  const totalHooksCount = gitHooksInstalled.length + installedData.pluginHooks.length;
  const hooksComplete = totalHooksCount > 0;

  const sidebarItems: SidebarItem[] = [
    { id: 'overview', label: 'Overview', icon: <Shield className="h-4 w-4" />, complete: health?.status === 'healthy' },
    { id: 'agents', label: 'Agents', icon: <Bot className="h-4 w-4" />, complete: installedData.agents.length > 0, count: installedData.agents.length },
    { id: 'skills', label: 'Skills', icon: <Sparkles className="h-4 w-4" />, complete: installedData.skills.length > 0, count: installedData.skills.length },
    { id: 'plugins', label: 'Plugins', icon: <Package className="h-4 w-4" />, complete: installedData.plugins.length > 0, count: installedData.plugins.length },
    { id: 'hooks', label: 'Hooks', icon: <Webhook className="h-4 w-4" />, complete: hooksComplete, count: totalHooksCount },
  ];

  return (
    <section className="h-full flex flex-col">
      <div className="mb-4 flex-shrink-0">
        <p className="text-sm text-muted-foreground">
          We've added guardrails so agentic coding behaves
        </p>
      </div>

      <div className="flex flex-1 border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden min-h-0 bg-white dark:bg-gray-900">
        <GuardrailsSidebar
          items={sidebarItems}
          activeItem={activeItem}
          onItemSelect={onItemSelect}
        />
        <div className="flex-1 p-4 overflow-y-auto">
          {activeItem === 'overview' && health && (
            <GuardrailOverviewContent health={health} flags={flags} repoId={repoId} onRunAnalysis={onRunAnalysis} onFlagsChange={onFlagsChange} analyzing={analyzing} hasClaudeCli={hasClaudeCli} />
          )}
          {activeItem === 'agents' && (
            <GuardrailListContent label="Agents" items={installedData.agents} icon={<Bot className="h-8 w-8 text-blue-400" />} />
          )}
          {activeItem === 'skills' && (
            <GuardrailListContent label="Skills" items={installedData.skills} icon={<Sparkles className="h-8 w-8 text-purple-400" />} />
          )}
          {activeItem === 'plugins' && (
            <GuardrailListContent label="Plugins" items={installedData.plugins} icon={<Package className="h-8 w-8 text-green-400" />} />
          )}
          {activeItem === 'hooks' && (
            <GuardrailHooksFullContent health={health} pluginHooks={installedData.pluginHooks} />
          )}
        </div>
      </div>
    </section>
  );
};

// --- Guardrail Content Panels ---

const flagValue = (flags: ConfigFlags | null, key: string, fallback: unknown = false): unknown =>
  flags?.[key]?.value ?? fallback;

const flagBool = (flags: ConfigFlags | null, key: string, fallback = false): boolean =>
  Boolean(flags?.[key]?.value ?? fallback);

const flagSource = (flags: ConfigFlags | null, key: string): 'default' | 'global' | 'repo' =>
  flags?.[key]?.source ?? 'default';

interface ModeCheckItem {
  label: string;
  complete: boolean;
  detail?: string;
}

const SourceBadge: React.FC<{ source: 'default' | 'global' | 'repo' }> = ({ source }) => {
  if (source === 'default') return null;
  const colors = source === 'repo'
    ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
    : 'bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-gray-400';
  return <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${colors}`}>{source}</span>;
};

interface ConfigInput {
  label: string;
  value: string;
  flagKey: string;
  onChange: (key: string, value: string) => void;
}

const ConfigTextInput: React.FC<ConfigInput> = ({ label, value, flagKey, onChange }) => (
  <div className="flex items-center justify-between text-sm py-1">
    <span className="text-muted-foreground">{label}</span>
    <input
      className="text-xs font-mono px-2 py-0.5 rounded border border-border bg-background w-32"
      value={value}
      onChange={(e) => onChange(flagKey, e.target.value)}
    />
  </div>
);

const ModeSection: React.FC<{
  label: string;
  description?: string;
  enabled: boolean;
  source?: 'default' | 'global' | 'repo';
  items?: ModeCheckItem[];
  inputs?: ConfigInput[];
  onToggle?: (enabled: boolean) => void;
}> = ({ label, description, enabled, source, items, inputs, onToggle }) => {
  const allConfigured = !items || items.every(item => item.complete);

  let badgeLabel: string;
  let badgeVariant: 'enabled' | 'misconfigured' | 'disabled';

  if (!enabled) {
    badgeLabel = 'Disabled';
    badgeVariant = 'disabled';
  } else if (allConfigured) {
    badgeLabel = 'Enabled';
    badgeVariant = 'enabled';
  } else {
    badgeLabel = 'Mis-configured';
    badgeVariant = 'misconfigured';
  }

  return (
    <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
      <div className="flex items-center justify-between px-3 py-2 bg-gray-50 dark:bg-gray-800/50">
        <span className="text-sm font-semibold">{label}</span>
        <div className="flex items-center gap-2">
          {source && <SourceBadge source={source} />}
          <FlagBadge label={badgeLabel} variant={badgeVariant} />
          {onToggle && (
            <Switch
              checked={enabled}
              onCheckedChange={onToggle}
              aria-label={`Toggle ${label}`}
            />
          )}
        </div>
      </div>
      {description && (
        <div className="px-3 py-1.5 border-t border-gray-100 dark:border-gray-800">
          <p className="text-xs text-muted-foreground">{description}</p>
        </div>
      )}
      {((items && items.length > 0) || (inputs && inputs.length > 0)) && (
        <div className="px-3 py-2 space-y-1.5 border-t border-gray-100 dark:border-gray-800">
          {items?.map(item => (
            <div key={item.label} className="flex items-center gap-2 text-sm">
              {item.complete ? (
                <CheckCircle2 className="h-4 w-4 text-green-500 flex-shrink-0" />
              ) : (
                <div className="h-4 w-4 rounded-full border-2 border-gray-300 dark:border-gray-600 flex-shrink-0" />
              )}
              <span className={item.complete ? 'text-foreground' : 'text-muted-foreground'}>{item.label}</span>
              {item.detail && (
                <span className="text-xs text-muted-foreground font-mono ml-auto">{item.detail}</span>
              )}
            </div>
          ))}
          {inputs?.map(input => (
            <ConfigTextInput key={input.flagKey} {...input} />
          ))}
        </div>
      )}
    </div>
  );
};

const GuardrailOverviewContent: React.FC<{
  health: ConfigHealth;
  flags: ConfigFlags | null;
  repoId: string;
  onRunAnalysis: () => void;
  onFlagsChange: (flags: ConfigFlags) => void;
  analyzing: boolean;
  hasClaudeCli: boolean;
}> = ({ health, flags, repoId, onRunAnalysis, onFlagsChange, analyzing, hasClaudeCli }) => {
  const allHooksInstalled = [health.hooks.preCommit, health.hooks.commitMsg, health.hooks.postCommit].every(h => h.installed && h.signed);
  const claudeMdPresent = health.contextBlock.present;
  const permissionsPresent = health.permissions.present && health.permissions.missing.length === 0;
  const directoriesComplete = health.directories.missing.length === 0;

  // Track pending text input changes (saved together via Save button)
  const [pendingTextChanges, setPendingTextChanges] = useState<Record<string, string>>({});
  const hasPendingChanges = Object.keys(pendingTextChanges).length > 0;

  const handleTextChange = (key: string, value: string) => {
    const originalValue = String(flagValue(flags, key, ''));
    if (value === originalValue) {
      setPendingTextChanges(prev => {
        const next = { ...prev };
        delete next[key];
        return next;
      });
    } else {
      setPendingTextChanges(prev => ({ ...prev, [key]: value }));
    }
  };

  const saveAllPending = async () => {
    for (const [key, value] of Object.entries(pendingTextChanges)) {
      await toggleFlag(key, value);
    }
    setPendingTextChanges({});
  };

  const toggleFlag = async (key: string, value: boolean | string) => {
    try {
      const res = await fetch(`/api/repos/${repoId}/feature-flags`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ key, value }),
      });
      if (res.ok) {
        const data = await res.json();
        onFlagsChange(data.flags);
      }
    } catch {
      // Silently fail — flag state unchanged
    }
  };

  const textValue = (key: string, fallback: string): string =>
    pendingTextChanges[key] ?? String(flagValue(flags, key, fallback));

  const tddItems: ModeCheckItem[] = [
    { label: 'Git hooks', complete: allHooksInstalled },
    { label: 'TDD workflow', complete: claudeMdPresent },
  ];

  const sddItems: ModeCheckItem[] = [
    { label: 'SDD workflow', complete: claudeMdPresent },
    { label: 'Permissions', complete: permissionsPresent },
  ];

  const adrItems: ModeCheckItem[] = [
    { label: 'ADR directory', complete: directoriesComplete },
  ];

  return (
    <div>
      <div className={`p-4 rounded-lg bg-gradient-to-r border sticky -top-4 -mx-4 -mt-4 z-10 rounded-t-none ${getStatusBg(health.status)}`}>
        <div className="flex items-center gap-3">
          {getStatusIcon(health.status)}
          <div className="flex-1">
            <p className="font-semibold">{getStatusLabel(health.status)}</p>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {health.status === 'healthy'
                ? 'Repository configuration is complete'
                : 'Re-run analysis to fix configuration issues'}
            </p>
          </div>
          {hasPendingChanges && (
            <Button onClick={saveAllPending} size="sm" variant="default">
              Save Changes
            </Button>
          )}
          {health.status !== 'healthy' && (
            <Tooltip>
              <TooltipTrigger asChild>
                <span>
                  <Button
                    onClick={onRunAnalysis}
                    disabled={!hasClaudeCli || analyzing}
                    size="sm"
                    variant="outline"
                  >
                    {analyzing ? (
                      <>
                        <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                        Fixing...
                      </>
                    ) : (
                      <>
                        <Play className="h-3.5 w-3.5 mr-1.5" />
                        Re-run Analysis
                      </>
                    )}
                  </Button>
                </span>
              </TooltipTrigger>
              {!hasClaudeCli && (
                <TooltipContent>
                  Claude CLI required - use the /analyse command in Claude Code instead
                </TooltipContent>
              )}
            </Tooltip>
          )}
        </div>
        {health.status !== 'healthy' && (() => {
          const issues = getConfigIssues(health);
          return issues.length > 0 ? (
            <ul data-testid="config-issues" className="mt-2 space-y-1">
              {issues.map((issue) => (
                <li key={issue} className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400">
                  <AlertCircle className="h-3.5 w-3.5 flex-shrink-0" />
                  {issue}
                </li>
              ))}
            </ul>
          ) : null;
        })()}
      </div>

      <div className="space-y-4 mt-4">
      <ModeSection
        label="Test Driven Development"
        description="Enforces red-green-refactor TDD cycle with git hooks that validate commit types and run tests."
        enabled={flagBool(flags, 'enableTDD', true)} source={flagSource(flags, 'enableTDD')} items={tddItems}
        onToggle={(v) => toggleFlag('enableTDD', v)}
      />
      <ModeSection
        label="Spec Driven Development"
        description="Plan features as PRDs before coding. Creates structured docs with features, tasks, and acceptance criteria."
        enabled={flagBool(flags, 'enableSDD', true)} source={flagSource(flags, 'enableSDD')} items={sddItems}
        inputs={[
          { label: 'PRD directory', value: textValue('prdDirectory', 'docs/prd'), flagKey: 'prdDirectory', onChange: handleTextChange },
          { label: 'Docs directory', value: textValue('docsDirectory', 'docs'), flagKey: 'docsDirectory', onChange: handleTextChange },
        ]}
        onToggle={(v) => toggleFlag('enableSDD', v)}
      />
      <ModeSection
        label="Architecture Decision Records"
        description="Document significant technical decisions with context, alternatives considered, and consequences."
        enabled={flagBool(flags, 'enableADR', true)} source={flagSource(flags, 'enableADR')} items={adrItems}
        inputs={[
          { label: 'ADR directory', value: textValue('adrDirectory', 'docs/adr'), flagKey: 'adrDirectory', onChange: handleTextChange },
        ]}
        onToggle={(v) => toggleFlag('enableADR', v)}
      />
      <ModeSection
        label="Adversarial Review"
        description="After each implementation commit, an adversarial reviewer challenges the work and suggests refactoring."
        enabled={flagBool(flags, 'enableAdversarial', true)} source={flagSource(flags, 'enableAdversarial')}
        onToggle={(v) => toggleFlag('enableAdversarial', v)}
      />
      <ModeSection
        label="Quality Analysis"
        description="Run comprehensive code quality analysis across 8 categories with weighted scoring."
        enabled={flagBool(flags, 'enableQuality', true)} source={flagSource(flags, 'enableQuality')}
        onToggle={(v) => toggleFlag('enableQuality', v)}
      />
      <ModeSection
        label="Auto-commit Progress"
        description="Automatically commit progress.json changes after task tracking instead of requiring a manual commit."
        enabled={flagBool(flags, 'autoCommitProgress')} source={flagSource(flags, 'autoCommitProgress')}
        onToggle={(v) => toggleFlag('autoCommitProgress', v)}
      />
      <ModeSection
        label="Auto-archive"
        description="Automatically archive PRDs and fixes when they are completed."
        enabled={flagBool(flags, 'autoArchive', true)} source={flagSource(flags, 'autoArchive')}
        onToggle={(v) => toggleFlag('autoArchive', v)}
      />
      <ModeSection
        label="Combine Red/Green Commits"
        description="Merge test and implementation into a single feat: commit instead of separate test: and feat: commits."
        enabled={flagBool(flags, 'combineRedGreenCommits')} source={flagSource(flags, 'combineRedGreenCommits')}
        onToggle={(v) => toggleFlag('combineRedGreenCommits', v)}
      />
      <ModeSection
        label="Manage AGENTS.md"
        description="Generate and maintain AGENTS.md during analyse with project context for agents."
        enabled={flagBool(flags, 'manageAgentsMd', true)} source={flagSource(flags, 'manageAgentsMd')}
        onToggle={(v) => toggleFlag('manageAgentsMd', v)}
      />
      <ModeSection
        label="Default Persona"
        description="Persona activated automatically at session start. Set to empty to disable."
        enabled={true}
        inputs={[
          { label: 'Persona', value: textValue('defaultPersona', 'developer'), flagKey: 'defaultPersona', onChange: handleTextChange },
        ]}
      />
      </div>
    </div>
  );
};


