const RecommendationsStep: React.FC<{
  repoId: string;
  recommendations: DashboardRecommendation[];
  dismissed: DismissedRecommendation[];
  dismissedExpanded: boolean;
  setDismissedExpanded: (expanded: boolean) => void;
  onAccept: (rec: DashboardRecommendation) => void;
  onDismiss: (rec: DashboardRecommendation) => void;
  onRestore: (item: DismissedRecommendation) => void;
  acceptingIds: Set<string>;
  acceptResults: Map<string, AcceptResult>;
  installedCapTypes: string[];
  tddEnabled: boolean;
  analysis: RepoAnalysisFile | null;
}> = ({ repoId, recommendations, dismissed, dismissedExpanded, setDismissedExpanded, onAccept, onDismiss, onRestore, acceptingIds, acceptResults, installedCapTypes, tddEnabled, analysis }) => {
  const [validationStates, setValidationStates] = useState<Record<string, RecommendationValidationState>>({});
  const [activeTab, setActiveTab] = useState<'pre-installed' | 'static-analysers' | 'recommendations'>(
    recommendations.length > 0 ? 'recommendations' : 'pre-installed'
  );

  interface DiscoveredCapability {
    id: string;
    name: string;
    emoji: string;
    category: string;
    version: string;
    agent: string;
    hasInstallSection: boolean;
    description: string;
  }
  const [discoveredCapabilities, setDiscoveredCapabilities] = useState<DiscoveredCapability[]>([]);

  useEffect(() => {
    fetch('/api/capabilities')
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (data?.capabilities) setDiscoveredCapabilities(data.capabilities);
      })
      .catch(() => {});
  }, []);
  const [commitPipeline, setCommitPipeline] = useState<PipelineStep[]>([ADVERSARIAL_STEP]);
  const [pushPipeline, setPushPipeline] = useState<PipelineStep[]>([]);
  const [qualityPipeline, setQualityPipeline] = useState<PipelineStep[]>([]);
  const [userInstalledCapabilities, setUserInstalledCapabilities] = useState<string[]>([]);
  const [pipelineSaving, setPipelineSaving] = useState(false);

  useEffect(() => {
    fetch(`/api/repos/${repoId}/pipeline`)
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (data?.pipeline) setCommitPipeline(data.pipeline);
        if (data?.pushPipeline) setPushPipeline(data.pushPipeline);
        if (data?.qualityPipeline) setQualityPipeline(data.qualityPipeline);
        if (data?.installedCapabilities) setUserInstalledCapabilities(data.installedCapabilities);
      })
      .catch(() => {});
  }, [repoId]);

  const savePipeline = async (type: 'commit' | 'push' | 'quality', steps: PipelineStep[]) => {
    if (type === 'commit') setCommitPipeline(steps);
    else if (type === 'push') setPushPipeline(steps);
    else setQualityPipeline(steps);
    setPipelineSaving(true);
    try {
      const body = type === 'commit'
        ? { pipeline: steps }
        : type === 'push'
          ? { pushPipeline: steps }
          : { qualityPipeline: steps };
      await fetch(`/api/repos/${repoId}/pipeline`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });
    } finally {
      setPipelineSaving(false);
    }
  };

  const handleAnalyse = async (rec: DashboardRecommendation) => {
    // Use cached validation from recommendation data if available
    if (rec.validation) {
      setValidationStates((prev) => ({
        ...prev,
        [rec.id]: { status: 'success', result: rec.validation as SkillValidationResult },
      }));
      return;
    }

    // No cached validation available - show fallback message
    setValidationStates((prev) => ({
      ...prev,
      [rec.id]: { status: 'error', message: 'Validation not available - accept to validate locally' },
    }));
  };
  // Built-in adversarial capability (always present, always installed)
  const adversarialCapability: CapabilityDashboardRecommendation = {
    id: 'builtin-adversarial',
    name: 'Adversarial Review',
    description: 'Critical code review from an isolated context after every implementation commit. Catches quality issues, missing tests, and suggests refactoring.',
    category: 'quality',
    reason: 'Pre-installed with plugin',
    tags: [],
    type: 'capability',
    installerId: 'adversarial',
    version: '1.0.0',
    stepDescriptions: [],
    trigger: 'commit',
    phaseEmoji: '\u{1F608}',
    phaseName: 'Adversarial Review',
    phaseDescription: 'Critical code review',
  };

  // Derive pipeline step type from a capability agent name:
  // "tiny-brain:coverage-reviewer" → "coverage", "dependency-audit-reviewer" → "dependency-audit"
  const deriveStepType = (agent: string) =>
    agent.replace(/^tiny-brain:/, '').replace(/-reviewer$/, '');

  // Filter out capability recommendations that overlap with pre-installed capabilities
  // Also filter superseded TBR names (security-scanning → security-review)
  const preInstalledIds = new Set(discoveredCapabilities.filter(c => !c.hasInstallSection).map(c => c.id));
  const supersededIds = new Set(['security-scanning']); // TBR names replaced by local capabilities
  const libraryCapRecs = recommendations
    .filter((r): r is CapabilityDashboardRecommendation => r.type === 'capability')
    .filter(r => !preInstalledIds.has(r.installerId) && !supersededIds.has(r.installerId));
  const atomicRecs = recommendations.filter(r => r.type !== 'capability');

  const groupedRecs = atomicRecs.reduce<Record<string, DashboardRecommendation[]>>((acc, rec) => {
    const group = acc[rec.type] ?? [];
    group.push(rec);
    acc[rec.type] = group;
    return acc;
  }, {});

  const typeOrder = ['skill', 'agent', 'hook'] as const;

  return (
    <section className="grid grid-cols-1 xl:grid-cols-2 gap-6">
      {/* Pipeline editors */}
      <div className="space-y-4">
        {(() => {
          // Build PipelineStep[] for all available capabilities
          // Merge steps from all pipelines + discovered capabilities + installed types
          const stepMap = new Map<string, PipelineStep>();
          // Adversarial is always available
          stepMap.set('adversarial', ADVERSARIAL_STEP);
          // Steps from active pipelines
          for (const step of [...commitPipeline, ...pushPipeline, ...qualityPipeline]) {
            stepMap.set(step.type, step);
          }
          // Steps from installed capabilities only (pre-installed or user-installed)
          // Derive the step type from the capability agent to check for overlap
          // e.g. capability "code-coverage" (agent "coverage-reviewer") → step type "coverage"
          const installedSet = new Set([...userInstalledCapabilities, ...discoveredCapabilities.filter(c => !c.hasInstallSection).map(c => c.id)]);
          for (const cap of discoveredCapabilities) {
            const derivedType = deriveStepType(cap.agent);
            if (installedSet.has(cap.id) && !stepMap.has(cap.id) && !stepMap.has(derivedType)) {
              stepMap.set(cap.id, { type: cap.id, agent: cap.agent, label: cap.name, emoji: cap.emoji });
            }
          }
          // Steps from installed types (may not have metadata — use sensible defaults)
          // Check if any existing step type is contained in the cap ID to avoid duplicates
          // e.g. skip "code-coverage" when step "coverage" already exists
          const existingTypes = [...stepMap.keys()];
          for (const t of [...installedCapTypes, ...userInstalledCapabilities]) {
            if (!stepMap.has(t) && !existingTypes.some(key => t.includes(key))) {
              stepMap.set(t, { type: t, agent: `tiny-brain:${t}-reviewer`, label: t, emoji: '\u{1F50D}' });
            }
          }
          // Steps from detected analyzers (from analysis.json)
          if (analysis?.analyzers) {
            for (const analyzer of analysis.analyzers) {
              if (!stepMap.has(analyzer.id)) {
                stepMap.set(analyzer.id, {
                  type: analyzer.id,
                  agent: `tiny-brain:analyzer-agent`,
                  label: analyzer.name,
                  emoji: analyzer.emoji ?? '\u{1F4CA}', // 📊
                  color: analyzer.color,
                  analyzer: analyzer.id,
                });
              }
            }
          }
          const allSteps = [...stepMap.values()];

          return (
            <>
              <div className="mb-3">
                <p className="text-xs text-muted-foreground">Drag to reorder. Use + to add steps, × to remove.</p>
                <div className="flex items-center gap-3 text-[10px] text-muted-foreground mt-1">
                  <span className="flex items-center gap-1"><span className="inline-block w-2 h-2 rounded-full bg-gray-400" />Static</span>
                  <span className="flex items-center gap-1"><span className="inline-block w-2 h-2 rounded-full bg-purple-500" />Agentic</span>
                  <span className="flex items-center gap-1"><span className="inline-block w-2 h-2 rounded-full bg-amber-500" />Tollgate</span>
                </div>
              </div>
              <div className="rounded-lg border border-border bg-gray-50 dark:bg-gray-800/50 p-4">
                <h3 className="text-sm font-semibold text-foreground mb-3">Per Commit</h3>
                <PipelineEditor
                  pipeline={commitPipeline}
                  available={allSteps}
                  onSave={(p) => savePipeline('commit', p)}
                  saving={pipelineSaving}
                  showFixedPhases={tddEnabled}
                  hookName="pre-commit"
                />
              </div>
              <div className="rounded-lg border border-border bg-gray-50 dark:bg-gray-800/50 p-4">
                <h3 className="text-sm font-semibold text-foreground mb-3">Per Push</h3>
                <PipelineEditor
                  pipeline={pushPipeline}
                  available={allSteps}
                  onSave={(p) => savePipeline('push', p)}
                  saving={pipelineSaving}
                  showFixedPhases={false}
                  hookName="pre-push"
                />
              </div>
              <div className="rounded-lg border border-border bg-gray-50 dark:bg-gray-800/50 p-4">
                <h3 className="text-sm font-semibold text-foreground mb-1">Quality</h3>
                <p className="text-xs text-muted-foreground mb-3">All enabled agents run in parallel during /quality analysis</p>
                <PipelineEditor
                  pipeline={qualityPipeline}
                  available={allSteps}
                  onSave={(p) => savePipeline('quality', p)}
                  saving={pipelineSaving}
                  showFixedPhases={false}
                  parallel
                />
              </div>
            </>
          );
        })()}
      </div>

      {/* Tabbed Pre-installed / Recommendations */}
      <div>
        <div className="flex border-b border-border mb-4">
          <button
            onClick={() => setActiveTab('pre-installed')}
            className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab === 'pre-installed'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            }`}
          >
            Pre-installed
            <Badge variant="secondary" className="ml-2">{discoveredCapabilities.filter(c => !c.hasInstallSection).length + 1}</Badge>
          </button>
          {analysis?.analyzers && analysis.analyzers.length > 0 && (
            <button
              onClick={() => setActiveTab('static-analysers')}
              className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                activeTab === 'static-analysers'
                  ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                  : 'border-transparent text-muted-foreground hover:text-foreground'
              }`}
            >
              Static Analysers
              <Badge variant="secondary" className="ml-2">{analysis?.analyzers?.length ?? 0}</Badge>
            </button>
          )}
          <button
            onClick={() => setActiveTab('recommendations')}
            className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab === 'recommendations'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            }`}
          >
            Recommendations
            {(() => {
              const installRequiredCount = discoveredCapabilities.filter(c => c.hasInstallSection && !userInstalledCapabilities.includes(c.id)).length;
              const total = installRequiredCount + atomicRecs.length;
              return total > 0 ? <Badge variant="secondary" className="ml-2">{total}</Badge> : null;
            })()}
          </button>
        </div>

        {activeTab === 'pre-installed' && (
          <div className="space-y-6">
            {/* Pre-installed capabilities (discovered from plugin) */}
            <div>
              <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wide mb-3 flex items-center gap-2">
                <Bot className="h-4 w-4" />
                Agentic Reviewers
                <Badge variant="secondary" className="ml-1">
                  {discoveredCapabilities.filter(c => !c.hasInstallSection).length + 1}
                </Badge>
              </h3>
              <div className="space-y-3">
                {/* Built-in adversarial (always first) */}
                <CapabilityCard
                  recommendation={adversarialCapability}
                  onAccept={() => {}}
                  onDismiss={() => {}}
                  isInstalled
                  isEnabled
                />
                {/* Discovered pre-installed capabilities (no Install section) */}
                {/* All pre-installed capabilities (informational) */}
                {discoveredCapabilities
                  .filter(cap => !cap.hasInstallSection)
                  .map(cap => (
                    <CapabilityCard
                      key={cap.id}
                      recommendation={{
                        id: `discovered-${cap.id}`,
                        name: cap.name,
                        description: cap.description,
                        category: cap.category,
                        reason: 'Pre-installed with plugin',
                        tags: [],
                        type: 'capability',
                        installerId: cap.id,
                        version: cap.version,
                        stepDescriptions: [],
                        trigger: 'commit',
                        phaseEmoji: cap.emoji,
                      }}
                      onAccept={() => {}}
                      onDismiss={() => {}}
                      isInstalled
                      isEnabled
                    />
                  ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'static-analysers' && analysis?.analyzers && (
          <div className="space-y-4">
            {analysis.analyzers.map(analyzer => {
              // Show the command that performs the analysis, shortened for readability
              const shortCmd = (analyzer.commands?.quality ?? '')
                .replace(/\s+\/\S+/g, '') // strip absolute paths
                .replace(/\{outputDir\}/g, '') // strip placeholder
                .replace(/\s+--\S*reportsDirectory\S*/g, '') // strip coverage dir flag
                .replace(/\s{2,}/g, ' ') // collapse whitespace
                .trim();
              return (
                <div
                  key={analyzer.id}
                  className="flex items-center gap-3 p-3 rounded-lg border border-gray-300 dark:border-gray-500 bg-gray-100 dark:bg-gray-600"
                >
                  <span className="text-xl">{analyzer.emoji ?? '\u{1F4CA}'}</span>
                  <div className="flex-1 min-w-0">
                    <div className="font-medium text-sm">{analyzer.name}</div>
                    <code className="text-[11px] text-muted-foreground font-mono">{shortCmd}</code>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {activeTab === 'recommendations' && (
          <div className="space-y-6">
            {/* Locally discovered capabilities needing install */}
            {(() => {
              const installRequired = discoveredCapabilities.filter(c => c.hasInstallSection);
              // Split into static analysers (CLI tools) vs agentic reviewers (LLM agents)
              const isStaticCap = (id: string) => !id.includes('review') && !id.includes('compliance');
              const staticCaps = installRequired.filter(c => isStaticCap(c.id));
              const agenticCaps = installRequired.filter(c => !isStaticCap(c.id));

              const renderCapSection = (caps: typeof installRequired, title: string, icon: React.ReactNode, variant: 'agentic' | 'static' = 'agentic') => {
                if (caps.length === 0) return null;
                return (
                  <div>
                    <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wide mb-3 flex items-center gap-2">
                      {icon}
                      {title}
                      <Badge variant="secondary" className="ml-1">{caps.length}</Badge>
                    </h3>
                    <div className="space-y-3">
                      {caps.map(cap => {
                        const isInstalled = userInstalledCapabilities.includes(cap.id);
                        return (
                          <CapabilityCard
                            key={cap.id}
                            recommendation={{
                              id: `discovered-${cap.id}`,
                              name: cap.name,
                              description: cap.description,
                              category: cap.category,
                              reason: isInstalled ? 'Installed' : 'Requires installation',
                              tags: [],
                              type: 'capability',
                              installerId: cap.id,
                              version: cap.version,
                              stepDescriptions: [],
                              trigger: 'commit',
                              phaseEmoji: cap.emoji,
                            }}
                            onAccept={() => {}}
                            onDismiss={() => {}}
                            isInstalled={isInstalled}
                            isEnabled={isInstalled}
                            variant={variant}
                          />
                        );
                      })}
                    </div>
                  </div>
                );
              };

              return (
                <>
                  {renderCapSection(staticCaps, 'Static Analysers', <Terminal className="h-4 w-4" />, 'static')}
                  {renderCapSection(agenticCaps, 'Agentic Reviewers', <Bot className="h-4 w-4" />, 'agentic')}
                </>
              );
            })()}

            {/* TBR-sourced capabilities hidden — local discovery handles capabilities */}

            {/* Recommended skills/agents/hooks */}
            {typeOrder.map(type => {
              const recs = groupedRecs[type];
              if (!recs || recs.length === 0) return null;

              return (
                <div key={type}>
                  <h3 className="text-sm font-medium text-muted-foreground uppercase tracking-wide mb-3 flex items-center gap-2">
                    {typeIcons[type]}
                    {type === 'skill' ? 'Skills' : type === 'agent' ? 'Agents' : 'Hooks'}
                    <Badge variant="secondary" className="ml-1">{recs.length}</Badge>
                  </h3>
                  <div className="space-y-3">
                    {recs.map(rec => (
                      <RecommendationCard
                        key={rec.id}
                        recommendation={rec}
                        onAccept={() => onAccept(rec)}
                        onDismiss={() => onDismiss(rec)}
                        isAccepting={acceptingIds.has(rec.id)}
                        acceptResult={acceptResults.get(rec.id)}
                        validationState={validationStates[rec.id]}
                        onAnalyse={() => handleAnalyse(rec)}
                      />
                    ))}
                  </div>
                </div>
              );
            })}

            {libraryCapRecs.length === 0 && atomicRecs.length === 0 && discoveredCapabilities.filter(c => c.hasInstallSection).length === 0 && (
              <p className="text-sm text-muted-foreground text-center py-8">No recommendations available</p>
            )}

            {/* Dismissed Section */}
            {dismissed.length > 0 && (
              <div className="mt-6 pt-4 border-t border-border">
                <button
                  onClick={() => setDismissedExpanded(!dismissedExpanded)}
                  className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
                >
                  {dismissedExpanded ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
                  <span>Dismissed</span>
                  <Badge variant="secondary">{dismissed.length}</Badge>
                </button>

                {dismissedExpanded && (
                  <div className="mt-3 space-y-2">
                    {dismissed.map(item => (
                      <div
                        key={item.recommendation.id}
                        className="flex items-center justify-between p-3 border border-border rounded-lg bg-muted/30"
                      >
                        <div className="flex items-center gap-3">
                          <span className={`text-xs px-2 py-0.5 rounded ${typeBadgeColors[item.recommendation.type]?.bg ?? ''} ${typeBadgeColors[item.recommendation.type]?.text ?? ''}`}>
                            {item.recommendation.type}
                          </span>
                          <span className="text-sm">{item.recommendation.name}</span>
                        </div>
                        <button
                          onClick={() => onRestore(item)}
                          className="text-xs px-2 py-1 rounded border border-border hover:bg-accent transition-colors"
                          aria-label={`Restore ${item.recommendation.name}`}
                        >
                          Restore
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </section>
  );
};

// --- Step 4: Ready ---

const ReadyStep: React.FC<{
  isGuardrailsComplete: boolean;
  isAnalysisComplete: boolean;
  isRecommendationsComplete: boolean;
  onNavigateToPlans: () => void;
}> = ({ isGuardrailsComplete, isAnalysisComplete, isRecommendationsComplete, onNavigateToPlans }) => {
  const isAllComplete = isGuardrailsComplete && isAnalysisComplete && isRecommendationsComplete;

  return (
    <section>
      {isAllComplete ? (
        <div className="mb-6 p-6 rounded-xl bg-gradient-to-br from-pink-50 via-purple-50 to-fuchsia-50 dark:from-pink-900/20 dark:via-purple-900/20 dark:to-fuchsia-900/20 border border-purple-100 dark:border-purple-800/50 text-center">
          <div className="text-4xl mb-3">{'\uD83C\uDF89'}</div>
          <p className="text-lg font-semibold text-purple-900 dark:text-purple-100">
            Your repo is set up for agentic coding
          </p>
          <p className="text-sm text-purple-600 dark:text-purple-300 mt-1">
            Everything is configured and ready to go
          </p>
        </div>
      ) : (
        <div className="mb-6 p-6 rounded-xl bg-gradient-to-br from-amber-50 via-yellow-50 to-orange-50 dark:from-amber-900/20 dark:via-yellow-900/20 dark:to-orange-900/20 border border-amber-100 dark:border-amber-800/50 text-center">
          <p className="text-lg font-semibold text-amber-900 dark:text-amber-100">
            Almost there
          </p>
          <p className="text-sm text-amber-600 dark:text-amber-300 mt-1">
            Complete the remaining steps to finish setup
          </p>
        </div>
      )}

      <div className="space-y-6">
        {/* Checklist */}
        <div className="space-y-3">
          <ChecklistItem label="Guardrails configured" complete={isGuardrailsComplete} />
          <ChecklistItem label="Repository analyzed" complete={isAnalysisComplete} />
          <ChecklistItem label="Recommendations reviewed" complete={isRecommendationsComplete} />
        </div>

        {/* Description */}
        <div className="p-4 rounded-lg bg-gray-50 dark:bg-gray-800/50 border border-gray-200 dark:border-gray-700">
          <p className="text-sm text-muted-foreground">
            The dashboard gives you visibility into your plans, fixes, and code quality as you work with agentic coding tools.
          </p>
        </div>

        {/* Start Planning Button */}
        <Button
          onClick={onNavigateToPlans}
          className="bg-blue-600 hover:bg-blue-700 text-white"
          size="lg"
        >
          Start planning
        </Button>
      </div>
    </section>
  );
};

const ChecklistItem: React.FC<{ label: string; complete: boolean }> = ({ label, complete }) => (
  <div className="flex items-center gap-3">
    {complete ? (
      <CheckCircle2 className="h-5 w-5 text-green-500" />
    ) : (
      <div className="h-5 w-5 rounded-full border-2 border-gray-300 dark:border-gray-600" />
    )}
    <span className={`text-sm ${complete ? 'text-foreground' : 'text-muted-foreground'}`}>
      {label}
    </span>
  </div>
);

export { ReadyStep, ChecklistItem };
export default SetupTab;
