'use client'

import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { FolderGit2, AlertCircle, Trash2, GitBranch } from 'lucide-react'

interface WorktreeEntry {
  name: string
  branch: string
  path: string
  lastActive: string
}

interface RepoInfo {
  id: string
  name: string
  path: string
  worktrees?: WorktreeEntry[]
}

export default function ReposPage() {
  console.log('[ReposPage] Component mounted');
  const navigate = useNavigate()
  const [repos, setRepos] = useState<RepoInfo[]>([])
  const [loading, setLoading] = useState(true)
  const [error] = useState<string | null>(null)
  const [repoToRemove, setRepoToRemove] = useState<RepoInfo | null>(null)

  useEffect(() => {
    console.log('[ReposPage] useEffect running, fetching repos...');
    fetchRepos()
  }, [])

  const fetchRepos = async () => {
    try {
      console.log('[ReposPage] Fetching from /api/repos...');
      const response = await fetch('/api/repos')
      console.log('[ReposPage] Response status:', response.status, response.ok);

      if (!response.ok) {
        console.log('[ReposPage] Response not OK, showing empty state');
        // If endpoint doesn't exist yet, show empty state
        setRepos([])
        setLoading(false)
        return
      }

      const data = await response.json()
      console.log('[ReposPage] Received data:', data);
      console.log('[ReposPage] Setting repos:', data.repos);
      setRepos(data.repos || [])
    } catch (err) {
      console.error('[ReposPage] Error fetching repos:', err)
      // On error, show empty state
      setRepos([])
    } finally {
      console.log('[ReposPage] Setting loading to false');
      setLoading(false)
    }
  }

  const confirmRemoveRepo = async () => {
    if (!repoToRemove) return

    try {
      const response = await fetch(`/api/repos/${repoToRemove.id}`, { method: 'DELETE' })
      if (response.ok) {
        setRepos(prev => prev.filter(r => r.id !== repoToRemove.id))
      }
    } catch (err) {
      console.error('[ReposPage] Error removing repo:', err)
    } finally {
      setRepoToRemove(null)
    }
  }

  if (loading) {
    return (
      <div className="p-6 space-y-4">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-32 w-full" />
      </div>
    )
  }

  if (error) {
    return (
      <div className="p-6">
        <div className="flex items-center gap-2 text-red-500">
          <AlertCircle className="h-5 w-5" />
          <span>{error}</span>
        </div>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      <div>
        <p className="text-muted-foreground mt-2">
          View and manage work across your repositories
        </p>
      </div>

      <div className="grid gap-4 grid-cols-2">
        {repos.map((repo) => (
          <Card
            key={repo.id}
            className="cursor-pointer hover:bg-accent transition-colors"
            onClick={() => {
              navigate(`/repos/${repo.id}`)
            }}
          >
            <CardHeader>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <FolderGit2 className="h-5 w-5 text-blue-500" />
                  <CardTitle className="text-lg">{repo.name}</CardTitle>
                </div>
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    setRepoToRemove(repo)
                  }}
                  className="p-1 rounded hover:bg-destructive/10 text-muted-foreground hover:text-destructive transition-colors"
                  aria-label={`Remove ${repo.name}`}
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </div>
              <CardDescription className="text-sm truncate">
                {repo.path}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {repo.worktrees && repo.worktrees.length > 0 && (
                <div className="flex items-center gap-1.5 mb-2">
                  <span className="inline-flex items-center gap-1 rounded-full bg-muted px-2.5 py-0.5 text-xs text-muted-foreground">
                    <GitBranch className="h-3 w-3" />
                    {repo.worktrees.length} {repo.worktrees.length === 1 ? 'worktree' : 'worktrees'}
                  </span>
                </div>
              )}
              <p className="text-sm text-muted-foreground">
                Click to view plans for this repository
              </p>
            </CardContent>
          </Card>
        ))}
      </div>

      {repos.length === 0 && (
        <Card>
          <CardContent className="pt-6">
            <div className="text-center text-muted-foreground">
              <FolderGit2 className="h-12 w-12 mx-auto mb-2 opacity-50" />
              <p>No repositories found</p>
            </div>
          </CardContent>
        </Card>
      )}

      <AlertDialog
        open={repoToRemove !== null}
        onOpenChange={(open) => {
          if (!open) setRepoToRemove(null)
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove Repository</AlertDialogTitle>
            <AlertDialogDescription>
              Remove &quot;{repoToRemove?.name}&quot; from the repos list? This won&apos;t delete any files on disk.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmRemoveRepo}>Remove</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}
