import { useState, useEffect } from 'react';
import { Routes, Route, useLocation, useNavigate, Navigate } from 'react-router-dom';
import { Layout } from './components/layout/Layout';
import { SidebarSection } from './components/layout/AppSidebar';
import { Drama, Settings, FolderGit2, Package } from 'lucide-react';
import TBSPersonasPage from './pages/TBSPersonasPage';
import PersonaDetailPage from './pages/PersonaDetailPage';
import ReposPage from './pages/ReposPage';
import RepoDetailPage from './pages/RepoDetailPage';
import SettingsPane from './components/SettingsPane';
import { PluginsPage } from './pages/PluginsPage';
import { usePersona } from './hooks/usePersona';
import { useSSE } from './hooks/useSSE';

function App() {
  const location = useLocation();
  const navigate = useNavigate();
  const { currentPersona, updatePersona } = usePersona();
  const sseState = useSSE();
  
  // Derive selectedView from current route
  const getSelectedView = () => {
    const path = location.pathname;
    if (path.startsWith('/personas')) return 'personas';
    if (path.startsWith('/repos')) return 'repos';
    if (path.startsWith('/plugins')) return 'plugins';
    if (path === '/settings') return 'settings';
    return 'personas';
  };
  
  const [selectedView, setSelectedView] = useState<string>(getSelectedView());
  
  // Update selectedView when route changes
  useEffect(() => {
    setSelectedView(getSelectedView());
  }, [location.pathname]);

  // Update persona when SSE reports a change
  useEffect(() => {
    if (sseState.personaId && sseState.personaId !== currentPersona) {
      console.log('[SSE] Persona changed to:', sseState.personaId);
      updatePersona(sseState.personaId);
    }
  }, [sseState.personaId, currentPersona, updatePersona]);

  // Define sidebar sections with items
  const sidebarSections: SidebarSection[] = [
    {
      id: 'main',
      items: [
        {
          id: 'personas',
          title: 'Personas',
          icon: Drama,
          color: 'text-orange-500'
        }
      ]
    },
    {
      id: 'code',
      title: 'Code',
      items: [
        {
          id: 'repos',
          title: 'Repos',
          icon: FolderGit2,
          color: 'text-blue-500'
        },
        {
          id: 'plugins',
          title: 'Plugins',
          icon: Package,
          color: 'text-purple-500'
        }
      ]
    },
    {
      id: 'other',
      title: 'Other',
      items: [
        {
          id: 'settings',
          title: 'Settings',
          icon: Settings,
          color: 'text-gray-500'
        }
      ]
    }
  ];

  const handleItemSelect = (itemId: string) => {
    console.log('[App] handleItemSelect called with:', itemId);
    setSelectedView(itemId);
    // Navigate to the appropriate route
    if (itemId === 'personas') navigate('/personas');
    else if (itemId === 'repos') {
      console.log('[App] Navigating to /repos');
      navigate('/repos');
    }
    else if (itemId === 'plugins') navigate('/plugins');
    else if (itemId === 'settings') navigate('/settings');
  };

  // Render content using React Router
  const renderContent = () => {
    return (
      <Routes>
        <Route path="/" element={<Navigate to="/personas" replace />} />
        <Route path="/personas" element={<TBSPersonasPage />} />
        <Route path="/personas/:personaId" element={<PersonaDetailPage />} />
        <Route path="/repos" element={<ReposPage />} />
        <Route path="/repos/:repoId" element={<RepoDetailPage />} />
        <Route path="/plugins" element={<PluginsPage />} />
        <Route path="/settings" element={<SettingsPane />} />
      </Routes>
    );
  };

  return (
    <Layout
      sidebarSections={sidebarSections}
      selectedItemId={selectedView}
      onItemSelect={handleItemSelect}
    >
      {renderContent()}
    </Layout>
  );
}

export default App;