import React from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { GitCommit } from 'lucide-react';
import type { Feature } from '../types';
import TaskRow from './TaskRow';
import { usePipelineConfig } from '../hooks/usePipelineConfig';

interface FeatureDetailProps {
  feature: Feature;
  repoId: string;
  onTaskClick?: (featureId: string, taskIndex: number, task: Feature['tasks'][0]) => void;
}

const FeatureDetail: React.FC<FeatureDetailProps> = ({ feature, repoId, onTaskClick }) => {
  const { pipeline: reviewPipeline } = usePipelineConfig(repoId);
  const completedTasks = feature.tasks?.filter(t => t.status === 'completed').length || 0;
  const supersededTasks = feature.tasks?.filter(t => t.status === 'superseded').length || 0;
  const doneTasks = completedTasks + supersededTasks;
  const totalTasks = feature.tasks?.length || 0;
  const progress = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;

  return (
    <div className="p-4 space-y-3">
      {/* Feature Description */}
      {feature.description && (
        <div className="px-3 py-2 bg-muted/50 rounded-md">
          <p className="text-sm text-muted-foreground">{feature.description}</p>
        </div>
      )}

      {/* Tasks List */}
      <div>
        <div className="flex items-center gap-2 mb-2">
          <GitCommit className="h-4 w-4 text-muted-foreground" />
          <span className="text-sm font-medium">Tasks</span>
        </div>
        <div>
          {totalTasks > 0 ? (
            <div className="space-y-1">
              {feature.tasks?.map((task, index) => (
                <TaskRow
                  key={task.id}
                  task={task}
                  repoId={repoId}
                  onClick={onTaskClick ? () => onTaskClick(feature.id, index + 1, task) : undefined}
                  reviewPipeline={reviewPipeline}
                />
              ))}
            </div>
          ) : (
            <p className="text-sm text-muted-foreground text-center py-4">
              No tasks defined for this feature
            </p>
          )}
        </div>
      </div>

      {/* Feature Timeline */}
      {(feature.startedAt || feature.completedAt) && (
        <Card>
          <CardContent className="pt-4">
            <div className="relative">
              {/* Progress percentage above the bar */}
              <div className="flex justify-between items-center mb-2">
                <span className="text-xs text-muted-foreground">Progress</span>
                <span className="text-sm font-semibold">{progress}%</span>
              </div>

              {/* Timeline bar - matching sidebar style */}
              <div className="relative h-2 rounded-full overflow-hidden bg-gray-200 dark:bg-gray-700">
                <div
                  className="absolute inset-y-0 left-0 transition-all duration-300"
                  style={{
                    width: `${feature.completedAt ? 100 : progress}%`,
                    backgroundColor: feature.status === 'completed' ? '#10b981' :
                                   feature.status === 'in_progress' ? '#3b82f6' : '#9ca3af'
                  }}
                />
              </div>

              {/* Timeline dates below bar */}
              <div className="flex justify-between mt-3 text-xs text-muted-foreground">
                {feature.startedAt && (
                  <span>{new Date(feature.startedAt).toLocaleDateString()}</span>
                )}
                {feature.completedAt && (
                  <span>{new Date(feature.completedAt).toLocaleDateString()}</span>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default FeatureDetail;
