/**
 * Server-Sent Events Manager
 *
 * Centralized SSE handling with automatic reconnection and type-safe event dispatch
 */

import type { Plan, Fix, RepoAnalysisFile } from '../types';
// SSE event types from core — imported for local use and re-exported for consumers
import type {
  PRDEventType,
  EventDelta,
  EventFeatureInfo,
  EventTaskInfo,
  FixEventType,
  QualityEventType,
  AnalysisEventType,
  AnalysisProgressEventType,
  SSEEventType,
  BaseSSEEvent,
  ConnectedEvent,
  ErrorEvent as CoreErrorEvent,
  AnalysisProgressSSEEvent,
  RecommendationsUpdatedEvent,
  QualityChangeEvent,
} from '@magic-ingredients/tiny-brain-core';
export type {
  PRDEventType,
  EventDelta,
  EventFeatureInfo,
  EventTaskInfo,
  FixEventType,
  QualityEventType,
  AnalysisEventType,
  AnalysisProgressEventType,
  SSEEventType,
  BaseSSEEvent,
  ConnectedEvent,
  AnalysisProgressSSEEvent,
  RecommendationsUpdatedEvent,
  QualityChangeEvent,
};

/**
 * Persona Change Event — uses dashboard Plan (has UI-specific fields)
 */
export interface PersonaChangeEvent extends BaseSSEEvent {
  type: 'personaChange' | 'persona-changed';
  personaId: string;
  plans?: Plan[];
  activePlanId?: string | null;
}

/**
 * Plan Change Event — uses dashboard Plan
 */
export interface PlanChangeEvent extends BaseSSEEvent {
  type: 'planChange';
  eventType?: PRDEventType;
  repoId?: string;
  prdId?: string;
  prdPath?: string;
  feature?: EventFeatureInfo;
  task?: EventTaskInfo;
  tasks?: EventTaskInfo[];
  delta?: EventDelta;
  plan?: Plan;
}

/**
 * Fix Change Event — uses dashboard Fix type (has testPlan, sourceWorktree)
 * which differs from core FixProgress (has qip). Intentional: the dashboard
 * Fix type is the canonical shape for UI rendering.
 */
export interface FixChangeEvent extends BaseSSEEvent {
  type: 'fixChange';
  eventType?: FixEventType;
  repoId?: string;
  fixId?: string;
  fix?: Fix;
  task?: Fix['tasks'][number];
  delta?: EventDelta;
}

/**
 * Analysis Change Event — uses dashboard RepoAnalysisFile
 */
export interface AnalysisChangeEvent extends BaseSSEEvent {
  type: 'analysisChange';
  eventType: AnalysisEventType;
  repoId: string;
  analysis?: RepoAnalysisFile;
  error?: string;
}

/**
 * Invalidate Event — uses dashboard Plan and Fix (typed, not any)
 */
export interface InvalidateEvent extends BaseSSEEvent {
  type: 'invalidate';
  resource: 'plan' | 'plans' | 'fix' | 'fixes';
  repoId: string;
  entities: Array<Plan | Fix>;
  worktree?: { name: string; branch: string };
}

export type SSEEvent = PersonaChangeEvent | PlanChangeEvent | FixChangeEvent | InvalidateEvent | QualityChangeEvent | AnalysisChangeEvent | AnalysisProgressSSEEvent | RecommendationsUpdatedEvent | ConnectedEvent | CoreErrorEvent;

class SSEManager {
  private eventSource: EventSource | null = null;
  private listeners: Map<SSEEventType, Set<(_event: SSEEvent) => void>> = new Map();
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 10;
  private reconnectDelay = 1000;
  private isConnected = false;
  private url: string;
  private isConnecting = false;

  constructor(url = '/events') {
    this.url = url;
    this.connect();
  }

  getCurrentState() {
    return {
      isConnected: this.isConnected,
      libraryConnected: null as number | null
    };
  }

  private connect() {
    // Prevent multiple simultaneous connections
    if (this.isConnecting || this.isConnected) {
      console.log('[SSE] Already connected or connecting, skipping...');
      return;
    }
    
    if (this.eventSource) {
      this.eventSource.close();
    }

    this.isConnecting = true;
    console.log('[SSE] 🔌 Connecting to', this.url);
    this.eventSource = new EventSource(this.url);

    this.eventSource.onopen = () => {
      console.log('[SSE] ✅ Connected successfully');
      this.isConnected = true;
      this.isConnecting = false;
      this.reconnectAttempts = 0;
      this.reconnectDelay = 1000;
    };

    // Listen for the 'connected' event specifically
    this.eventSource.addEventListener('connected', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const connectedEvent: ConnectedEvent = {
          type: 'connected',
          timestamp: new Date().toISOString(),
          libraryConnected: data.libraryConnected ?? 401
        };

        console.log('[SSE] 🔗 Connected to server');
        console.log(`[SSE]    Library status: ${connectedEvent.libraryConnected}`);

        this.dispatch(connectedEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse connected event:', error, event.data);
      }
    });

    // Listen for 'persona-changed' events
    this.eventSource.addEventListener('persona-changed', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const personaEvent: PersonaChangeEvent = {
          type: 'persona-changed',
          timestamp: data.timestamp || new Date().toISOString(),
          personaId: data.personaId,
          plans: data.plans,
          activePlanId: data.activePlanId
        };

        console.log(`[SSE] 👤 Persona changed to '${personaEvent.personaId}'`);

        this.dispatch(personaEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse persona-changed event:', error, event.data);
      }
    });

    // Listen for 'plan-change' events
    this.eventSource.addEventListener('plan-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const planEvent: PlanChangeEvent = {
          type: 'planChange',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          prdId: data.prdId,
          prdPath: data.prdPath,
          feature: data.feature,
          task: data.task,
          tasks: data.tasks,
          delta: data.delta,
          plan: data.plan
        };

        // Enhanced logging for granular events
        if (planEvent.eventType) {
          const eventTypeLabel = {
            'prd:created': '🆕 PRD Created',
            'prd:feature:added': '➕ Feature Added',
            'prd:feature:updated': '🔄 Feature Updated',
            'prd:feature:tasks:added': '📝 Tasks Added',
            'prd:feature:task:completed': '✅ Task Completed',
            'prd:feature:task:updated': '🔧 Task Updated'
          }[planEvent.eventType] || '📋 Plan Change';

          console.log(`[SSE] ${eventTypeLabel}: ${planEvent.prdId}`);
        } else {
          console.log(`[SSE] 📋 Plan Change`);
        }
        if (planEvent.feature) {
          console.log(`[SSE]    Feature: ${planEvent.feature.title} (${planEvent.feature.status})`);
        }
        if (planEvent.task) {
          console.log(`[SSE]    Task: ${planEvent.task.description}`);
        }
        if (planEvent.tasks && planEvent.tasks.length > 0) {
          console.log(`[SSE]    Tasks added: ${planEvent.tasks.length}`);
        }
        if (planEvent.delta) {
          if (planEvent.delta.tasksAdded) console.log(`[SSE]    +${planEvent.delta.tasksAdded} tasks`);
          if (planEvent.delta.tasksCompleted) console.log(`[SSE]    ✓${planEvent.delta.tasksCompleted} tasks`);
        }

        this.dispatch(planEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse plan-change event:', error, event.data);
      }
    });

    // Listen for 'fix-change' events (legacy — kept for backward compat with index.ts relay)
    this.eventSource.addEventListener('fix-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const fixEvent: FixChangeEvent = {
          type: 'fixChange',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          fixId: data.fixId,
          fix: data.fix,
          task: data.task,
          delta: data.delta
        };

        console.log(`[SSE] 🐛 Fix Change (legacy): ${fixEvent.fixId || 'all'}`);
        this.dispatch(fixEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse fix-change event:', error, event.data);
      }
    });

    // Listen for 'invalidate' events (entity-push invalidation from file watcher)
    this.eventSource.addEventListener('invalidate', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const invalidateEvent: InvalidateEvent = {
          type: 'invalidate',
          timestamp: data.timestamp || new Date().toISOString(),
          resource: data.resource,
          repoId: data.repoId,
          entities: data.entities || [],
          ...(data.worktree ? { worktree: data.worktree } : {}),
        };

        console.log(`[SSE] 🔄 Invalidate: ${invalidateEvent.resource} (${invalidateEvent.entities.length} entities) for repo ${invalidateEvent.repoId}`);
        this.dispatch(invalidateEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse invalidate event:', error, event.data);
      }
    });

    // Listen for 'analysis-progress' events (streaming progress during analysis)
    this.eventSource.addEventListener('analysis-progress', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const progressEvent: AnalysisProgressSSEEvent = {
          type: 'analysisProgress',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          message: data.message,
          data: data.data
        };

        // Enhanced logging for progress events
        const stepLabels: Record<string, string> = {
          'analysis:started': '🚀 Started',
          'analysis:tech-detection': '🔍 Detecting tech stack',
          'analysis:writing-file': '📝 Writing analysis.json',
          'analysis:fetching-contexts': '📥 Fetching tech contexts',
          'analysis:syncing-agents': '🔄 Syncing agents',
          'analysis:generating-agents-md': '📄 Generating AGENTS.md',
          'analysis:config-setup': '⚙️ Setting up configuration',
          'analysis:complete': '✅ Complete',
          'analysis:failed': '❌ Failed'
        };
        const label = stepLabels[progressEvent.eventType] || progressEvent.eventType;
        console.log(`[SSE] Analysis Progress: ${label}`);

        this.dispatch(progressEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse analysis-progress event:', error, event.data);
      }
    });

    // Listen for 'analysis-change' events (final completion/failure)
    this.eventSource.addEventListener('analysis-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const analysisEvent: AnalysisChangeEvent = {
          type: 'analysisChange',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          analysis: data.analysis,
          error: data.error
        };

        // Enhanced logging for analysis events
        const eventTypeLabel = analysisEvent.eventType === 'analysis:complete'
          ? '✅ Analysis Complete'
          : '❌ Analysis Failed';

        console.log(`[SSE] ${eventTypeLabel}: ${analysisEvent.repoId}`);
        if (analysisEvent.error) {
          console.log(`[SSE]    Error: ${analysisEvent.error}`);
        }

        this.dispatch(analysisEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse analysis-change event:', error, event.data);
      }
    });

    // Listen for 'quality-change' events
    this.eventSource.addEventListener('quality-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const qualityEvent: QualityChangeEvent = {
          type: 'qualityChange',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          runId: data.runId,
          run: data.run
        };

        const eventLabels: Record<string, string> = {
          'quality:created': '🆕 Quality Run Created',
          'quality:updated': '🔄 Quality Run Updated',
          'quality:deleted': '🗑️ Quality Run Deleted'
        };
        const label = qualityEvent.eventType ? (eventLabels[qualityEvent.eventType] || '📊 Quality Change') : '📊 Quality Change';
        console.log(`[SSE] ${label}: ${qualityEvent.runId}`);

        this.dispatch(qualityEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse quality-change event:', error, event.data);
      }
    });

    // Listen for 'recommendations-updated' events
    this.eventSource.addEventListener('recommendations-updated', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const recsEvent: RecommendationsUpdatedEvent = {
          type: 'recommendationsUpdated',
          timestamp: data.timestamp || new Date().toISOString(),
          repoId: data.repoId,
          added: data.added,
          updated: data.updated,
        };

        console.log(`[SSE] 📦 Recommendations Updated: ${recsEvent.repoId} (+${recsEvent.added} new, ${recsEvent.updated} updated)`);

        this.dispatch(recsEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse recommendations-updated event:', error, event.data);
      }
    });

    this.eventSource.onmessage = (event) => {
      try {
        const data: SSEEvent = JSON.parse(event.data);
        console.log('[SSE] Received event:', data.type);
        this.dispatch(data);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse event:', error, event.data);
      }
    };

    this.eventSource.onerror = (error) => {
      console.error('[SSE] ❌ Connection error - Is the plan watcher running?');
      console.error('[SSE]    Start it with: watch plans');
      console.error('[SSE]    Error details:', error);
      this.isConnected = false;
      this.eventSource?.close();
      
      // Dispatch error event
      this.dispatch({
        type: 'error',
        timestamp: new Date().toISOString(),
        error: 'Connection lost - Plan watcher may not be running'
      });
      
      // Attempt reconnection
      if (this.reconnectAttempts < this.maxReconnectAttempts) {
        const delay = this.reconnectDelay;
        console.log(`[SSE] Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts + 1}/${this.maxReconnectAttempts})`);
        
        setTimeout(() => {
          this.reconnectAttempts++;
          this.reconnectDelay = Math.min(this.reconnectDelay * 2, 30000);
          this.connect();
        }, delay);
      } else {
        console.error('[SSE] Max reconnection attempts reached');
      }
    };
  }

  private dispatch(event: SSEEvent) {
    const listeners = this.listeners.get(event.type);
    if (listeners) {
      listeners.forEach(listener => {
        try {
          listener(event);
        } catch (error) {
          console.error('[SSE] Listener error:', error);
        }
      });
    }
    
    // Also dispatch to wildcard listeners
    const wildcardListeners = this.listeners.get('*' as SSEEventType);
    if (wildcardListeners) {
      wildcardListeners.forEach(listener => {
        try {
          listener(event);
        } catch (error) {
          console.error('[SSE] Wildcard listener error:', error);
        }
      });
    }
  }

  /**
   * Subscribe to SSE events
   * @param eventType The type of event to listen for (or '*' for all events)
   * @param listener The callback function
   * @returns Unsubscribe function
   */
  on(eventType: SSEEventType | '*', listener: (_event: SSEEvent) => void): () => void {
    const key = eventType as SSEEventType;
    if (!this.listeners.has(key)) {
      this.listeners.set(key, new Set());
    }
    this.listeners.get(key)!.add(listener);
    
    // Return unsubscribe function
    return () => {
      this.listeners.get(key)?.delete(listener);
    };
  }

  /**
   * Close the SSE connection
   */
  disconnect() {
    if (this.eventSource) {
      console.log('[SSE] Disconnecting');
      this.eventSource.close();
      this.eventSource = null;
      this.isConnected = false;
    }
  }

  /**
   * Manually reconnect
   */
  reconnect() {
    this.reconnectAttempts = 0;
    this.connect();
  }

  /**
   * Check if connected
   */
  getIsConnected(): boolean {
    return this.isConnected;
  }
}

// Export singleton instance
export const sseManager = new SSEManager();

// Export for testing
export { SSEManager };