/**
 * Color utilities for step card theming.
 * Expects 6-digit hex colors (e.g. "#4caf50").
 */

/** Parse a 6-digit hex color to [r, g, b] (0-255). */
export function hexToRgb(hex: string): [number, number, number] {
  const h = hex.replace('#', '');
  return [
    parseInt(h.substring(0, 2), 16),
    parseInt(h.substring(2, 4), 16),
    parseInt(h.substring(4, 6), 16),
  ];
}

/** Derive a lighter tint from a hex color for card backgrounds. */
export function tintColor(hex: string, amount: number): string {
  const [r, g, b] = hexToRgb(hex);
  const t = (v: number) => Math.round(v + (255 - v) * amount);
  return `rgb(${t(r)}, ${t(g)}, ${t(b)})`;
}

/** Derive a darker tint from a hex color for dark-mode card backgrounds. */
export function darkTintColor(hex: string, amount: number): string {
  const [r, g, b] = hexToRgb(hex);
  const t = (v: number) => Math.round(v * (1 - amount));
  return `rgb(${t(r)}, ${t(g)}, ${t(b)})`;
}

/** Derive a semi-transparent border from a hex color. */
export function borderColor(hex: string): string {
  const [r, g, b] = hexToRgb(hex);
  return `rgba(${r}, ${g}, ${b}, 0.35)`;
}
